    fn draw_shaded_textured_quad(
        &mut self,
        words: &[u32],
        source: Option<&GpuCommandSource>,
        vertices: [(u32, u32, u32); 4],
    ) {
        self.textured_triangle_commands += 2;
        let [
            (a, a_uv, a_color),
            (b, b_uv, b_color),
            (c, c_uv, c_color),
            (d, d_uv, d_color),
        ] = vertices;
        let clut = clut(a_uv);
        let texture_page = self.set_polygon_texture_page(texture_page(b_uv));
        let mut options = self.texture_draw_options(words[0], texture_page);
        let a = self.textured_point(a, a_uv);
        let b = self.textured_point(b, b_uv);
        let c = self.textured_point(c, c_uv);
        let d = self.textured_point(d, d_uv);
        let bounds = points_bounds(&[a.point, b.point, c.point, d.point]);
        if should_allow_br2_character_select_polygon_palette_fallback(
            words[0],
            texture_page,
            clut,
            bounds,
        ) || should_allow_br2_gameplay_polygon_palette_fallback(
            words[0],
            texture_page,
            clut,
            bounds,
        ) {
            options.allow_palette_fallback = true;
        }
        let a_color = command_color(a_color);
        let b_color = command_color(b_color);
        let c_color = command_color(c_color);
        let d_color = command_color(d_color);
        let adjusted_clip = self.apply_drawing_clip_for_bounds(bounds, true);
        let (first, second) = if should_skip_br2_stale_character_select_stage_atlas_strip(
            texture_page,
            clut,
            bounds,
            &[a, b, c, d],
        ) {
            (TexturedDrawStats::default(), TexturedDrawStats::default())
        } else if native_use_alternate_quad_split() {
            (
                self.framebuffer.draw_shaded_textured_triangle(
                    a,
                    b,
                    d,
                    [a_color, b_color, d_color],
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
                self.framebuffer.draw_shaded_textured_triangle(
                    a,
                    c,
                    d,
                    [a_color, c_color, d_color],
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
            )
        } else {
            (
                self.framebuffer.draw_shaded_textured_triangle(
                    a,
                    b,
                    c,
                    [a_color, b_color, c_color],
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
                self.framebuffer.draw_shaded_textured_triangle(
                    b,
                    c,
                    d,
                    [b_color, c_color, d_color],
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
            )
        };
        self.restore_drawing_clip_if(adjusted_clip);
        self.add_textured_draw_stats(first);
        self.add_textured_draw_stats(second);
        self.push_recent_draw_command(GpuDrawTrace::textured_with_options(
            "shaded_textured_quad",
            texture_page,
            clut,
            bounds,
            combine_textured_draw_stats(first, second),
            words,
            &[a, b, c, d],
            self.texture_window,
            options,
            source,
        ));
    }

    fn draw_textured_quad(
        &mut self,
        words: &[u32],
        source: Option<&GpuCommandSource>,
        vertices: [(u32, u32); 4],
    ) {
        self.textured_triangle_commands += 2;
        let [(a, a_uv), (b, b_uv), (c, c_uv), (d, d_uv)] = vertices;
        let clut = clut(a_uv);
        let texture_page = self.set_polygon_texture_page(texture_page(b_uv));
        let mut options = self.texture_draw_options(words[0], texture_page);
        let a = self.textured_point(a, a_uv);
        let b = self.textured_point(b, b_uv);
        let c = self.textured_point(c, c_uv);
        let d = self.textured_point(d, d_uv);
        let bounds = points_bounds(&[a.point, b.point, c.point, d.point]);
        if should_allow_br2_character_select_polygon_palette_fallback(
            words[0],
            texture_page,
            clut,
            bounds,
        ) || should_allow_br2_gameplay_polygon_palette_fallback(
            words[0],
            texture_page,
            clut,
            bounds,
        ) {
            options.allow_palette_fallback = true;
        }
        let adjusted_clip = self.apply_drawing_clip_for_bounds(bounds, true);
        let (first, second) = if should_skip_noisy_4bpp_title_draw(texture_page, clut, bounds)
            || should_skip_br2_stale_character_select_stage_atlas_strip(
                texture_page,
                clut,
                bounds,
                &[a, b, c, d],
            ) {
            (TexturedDrawStats::default(), TexturedDrawStats::default())
        } else if native_use_alternate_quad_split() {
            (
                self.framebuffer.draw_textured_triangle(
                    a,
                    b,
                    d,
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
                self.framebuffer.draw_textured_triangle(
                    a,
                    c,
                    d,
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
            )
        } else {
            (
                self.framebuffer.draw_textured_triangle(
                    a,
                    b,
                    c,
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
                self.framebuffer.draw_textured_triangle(
                    b,
                    c,
                    d,
                    texture_page,
                    clut,
                    options,
                    self.texture_window,
                ),
            )
        };
        self.restore_drawing_clip_if(adjusted_clip);
        self.add_textured_draw_stats(first);
        self.add_textured_draw_stats(second);
        self.push_recent_draw_command(GpuDrawTrace::textured_with_options(
            "textured_quad",
            texture_page,
            clut,
            bounds,
            combine_textured_draw_stats(first, second),
            words,
            &[a, b, c, d],
            self.texture_window,
            options,
            source,
        ));
    }

    fn draw_textured_rect(
        &mut self,
        words: &[u32],
        source: Option<&GpuCommandSource>,
        xy: u32,
        uv: u32,
        width: i32,
        height: i32,
    ) {
        self.textured_rect_commands += 1;
        let point = self.offset_point(point(xy));
        let texture_uv = texture_coordinate(uv);
        let mut options = self.texture_draw_options(words[0], self.texture_page);
        let clut = clut(uv);
        let bounds = rect_bounds(point, width, height);
        let disable_br2_blank_clut_fallback =
            should_disable_br2_blank_clut_screen_rect_palette_fallback(
                words[0],
                self.texture_page,
                clut,
                bounds,
            );
        let disable_zn_4bpp_fallback = should_disable_zn_low_bank_4bpp_screen_rect_palette_fallback(
            words[0],
            self.texture_page,
            clut,
            bounds,
        ) && !self.has_native_play_3d_draw_signal();
        if disable_br2_blank_clut_fallback || disable_zn_4bpp_fallback {
            options.allow_palette_fallback = false;
        } else if should_allow_zn_low_bank_screen_rect_palette_fallback(
            words[0],
            self.texture_page,
            clut,
            bounds,
        ) {
            options.allow_palette_fallback = true;
        }
        let adjusted_clip = self.apply_drawing_clip_for_bounds(bounds, true);
        let skip_draw = should_skip_noisy_4bpp_title_draw(self.texture_page, clut, bounds);
        let stats = if skip_draw {
            TexturedDrawStats::default()
        } else {
            self.framebuffer.draw_textured_rect(
                point,
                (width, height),
                self.texture_page,
                clut,
                texture_uv,
                options,
                self.texture_window,
            )
        };
        self.restore_drawing_clip_if(adjusted_clip);
        self.add_textured_draw_stats(stats);
        let textured_point = TexturedPoint {
            point,
            u: texture_uv.u,
            v: texture_uv.v,
        };
        self.push_recent_draw_command(GpuDrawTrace::textured_with_options(
            "textured_rect",
            self.texture_page,
            clut,
            bounds,
            stats,
            words,
            &[textured_point],
            self.texture_window,
            options,
            source,
        ));
    }

    fn add_textured_draw_stats(&mut self, stats: TexturedDrawStats) {
        self.textured_draw_stats.sampled_pixels = self
            .textured_draw_stats
            .sampled_pixels
            .saturating_add(stats.sampled_pixels);
        self.textured_draw_stats.drawn_pixels = self
            .textured_draw_stats
            .drawn_pixels
            .saturating_add(stats.drawn_pixels);
        self.textured_draw_stats.written_pixels = self
            .textured_draw_stats
            .written_pixels
            .saturating_add(stats.written_pixels);
        self.textured_draw_stats.clipped_pixels = self
            .textured_draw_stats
            .clipped_pixels
            .saturating_add(stats.clipped_pixels);
        self.textured_draw_stats.transparent_pixels = self
            .textured_draw_stats
            .transparent_pixels
            .saturating_add(stats.transparent_pixels);
        self.textured_draw_stats.texture_nonzero_samples = self
            .textured_draw_stats
            .texture_nonzero_samples
            .saturating_add(stats.texture_nonzero_samples);
        self.textured_draw_stats.zero_texel_samples = self
            .textured_draw_stats
            .zero_texel_samples
            .saturating_add(stats.zero_texel_samples);
        self.textured_draw_stats.clut_nonzero_samples = self
            .textured_draw_stats
            .clut_nonzero_samples
            .saturating_add(stats.clut_nonzero_samples);
        self.textured_draw_stats.clut_blank_samples = self
            .textured_draw_stats
            .clut_blank_samples
            .saturating_add(stats.clut_blank_samples);
        self.textured_draw_stats.palette_fallback_samples = self
            .textured_draw_stats
            .palette_fallback_samples
            .saturating_add(stats.palette_fallback_samples);
        self.textured_draw_stats.nonzero_texel_transparent_samples = self
            .textured_draw_stats
            .nonzero_texel_transparent_samples
            .saturating_add(stats.nonzero_texel_transparent_samples);
        if stats.drawn_pixels != 0 {
            if self.textured_draw_stats.drawn_pixels == stats.drawn_pixels {
                self.textured_draw_stats.first_color = stats.first_color;
            } else if self.textured_draw_stats.last_color != stats.first_color {
                self.textured_draw_stats.color_changes =
                    self.textured_draw_stats.color_changes.saturating_add(1);
            }
            self.textured_draw_stats.last_color = stats.last_color;
            self.textured_draw_stats.color_hash ^= stats.color_hash;
            self.textured_draw_stats.color_hash =
                self.textured_draw_stats.color_hash.wrapping_mul(16_777_619);
            self.textured_draw_stats.color_changes = self
                .textured_draw_stats
                .color_changes
                .saturating_add(stats.color_changes);
        }
    }

    fn textured_point(&self, xy: u32, uv: u32) -> TexturedPoint {
        TexturedPoint {
            point: self.offset_point(point(xy)),
            u: (uv & 0xff) as u8,
            v: ((uv >> 8) & 0xff) as u8,
        }
    }

    fn offset_point(&self, point: Point) -> Point {
        let (x, y) = drawing_offset_xy(self.drawing_offset);
        let (recovery_x, recovery_y) = self.recovery_overlay_translation.unwrap_or((0, 0));
        let mut offset_point = Point {
            x: point.x + x + recovery_x,
            y: point.y + y + recovery_y,
        };
        if self.should_recover_absolute_field_y(point.y, offset_point.y, y) {
            offset_point.y = point.y + recovery_y;
        }
        offset_point
    }

    fn should_recover_absolute_field_y(
        &self,
        raw_y: i32,
        offset_y: i32,
        drawing_offset_y: i32,
    ) -> bool {
        if self.recovery_overlay_translation.is_some() || drawing_offset_y == 0 {
            return false;
        }

        let Some(clip) =
            drawing_area_clip(self.drawing_area_top_left, self.drawing_area_bottom_right)
        else {
            return false;
        };
        let page_height = clip.bottom.saturating_sub(clip.top) + 1;
        page_height > 0
            && drawing_offset_y.unsigned_abs() == page_height as u32
            && (drawing_offset_y == clip.top || clip.top == 0)
            && (clip.top..=clip.bottom).contains(&raw_y)
            && !(clip.top..=clip.bottom).contains(&offset_y)
    }

    fn recovery_offset_flat_rect_point(&self, point: Point) -> Point {
        if self.recovery_overlay_translation.is_some() {
            self.offset_point(point)
        } else {
            point
        }
    }

    fn update_drawing_clip(&mut self) {
        let mut clip =
            drawing_area_clip(self.drawing_area_top_left, self.drawing_area_bottom_right);
        if let (Some(current), Some((x, y))) = (clip, self.recovery_overlay_translation) {
            clip = ClipRect::new(
                current.left.saturating_add(x),
                current.top.saturating_add(y),
                current.right.saturating_add(x),
                current.bottom.saturating_add(y),
            );
        }
        self.framebuffer.set_clip(clip);
    }

    fn apply_drawing_clip_for_bounds(&mut self, bounds: DrawBounds, textured: bool) -> bool {
        let Some(current_clip) =
            drawing_area_clip(self.drawing_area_top_left, self.drawing_area_bottom_right)
        else {
            return false;
        };
        let Some(field_local_clip) =
            self.high_vertical_field_local_drawing_clip_for_bounds(bounds, current_clip, textured)
        else {
            return false;
        };
        if field_local_clip == current_clip {
            return false;
        }

        if self.recovered_draw_page_tracking {
            self.recovered_field_local_clip = Some(field_local_clip);
        }
        self.framebuffer.set_clip(Some(field_local_clip));
        true
    }

    fn restore_drawing_clip_if(&mut self, adjusted: bool) {
        if adjusted {
            self.update_drawing_clip();
        }
    }

    fn high_vertical_field_local_drawing_clip_for_bounds(
        &self,
        bounds: DrawBounds,
        current_clip: ClipRect,
        textured: bool,
    ) -> Option<ClipRect> {
        let (_, display_height) = self.display_dimensions();
        if native_disable_high_vertical_field_local_clip()
            || !textured
            || !self.high_vertical_field_local_clip_runtime_ready()
            || !self.high_vertical_interlace_enabled()
            || display_height < DEFAULT_DISPLAY_HEIGHT * 2
            || !display_height.is_multiple_of(2)
        {
            return None;
        }

        let field_height = i32::try_from(display_height / 2).ok()?;
        if field_height <= 0 || field_height > PSX_VRAM_HEIGHT as i32 {
            return None;
        }
        let clip_height = current_clip.bottom.saturating_sub(current_clip.top) + 1;
        if clip_height <= 0 || clip_height > field_height {
            return None;
        }
        let shifted = if current_clip.top >= field_height
            && current_clip.bottom < field_height.saturating_mul(2)
        {
            ClipRect::new(
                current_clip.left,
                current_clip.top - field_height,
                current_clip.right,
                current_clip.bottom - field_height,
            )?
        } else if current_clip.bottom < field_height {
            ClipRect::new(
                current_clip.left,
                current_clip.top + field_height,
                current_clip.right,
                current_clip.bottom + field_height,
            )?
        } else {
            return None;
        };

        let current_overlap = draw_bounds_clip_intersection_area(bounds, current_clip);
        let shifted_overlap = draw_bounds_clip_intersection_area(bounds, shifted);
        (shifted_overlap > current_overlap).then_some(shifted)
    }

    fn high_vertical_field_local_clip_runtime_ready(&self) -> bool {
        self.has_strong_native_3d_textured_playfield_activity()
            || self.has_strong_streamed_scene_rect_activity()
    }

    fn pixel_write_options(&self) -> PixelWriteOptions {
        PixelWriteOptions {
            set_mask_bit: self.set_mask_bit,
            check_mask_bit: self.check_mask_bit,
            semi_transparent: false,
            semi_transparency_mode: 0,
        }
    }

    fn flat_draw_options(&self, command_word: u32) -> PixelWriteOptions {
        PixelWriteOptions {
            set_mask_bit: self.set_mask_bit,
            check_mask_bit: self.check_mask_bit,
            semi_transparent: command_word & 0x0200_0000 != 0,
            semi_transparency_mode: ((self.texture_page >> 5) & 0x03) as u8,
        }
    }

    fn texture_draw_options(&self, command_word: u32, texture_page: u16) -> TextureDrawOptions {
        let mut options = texture_draw_options(command_word, texture_page);
        options.set_mask_bit = self.set_mask_bit;
        options.check_mask_bit = self.check_mask_bit;
        options
    }

