#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct NativeGpuDrawCapturePredicate {
    pub kind: Option<String>,
    pub texture_page: Option<u16>,
    pub clut: Option<u16>,
    pub min_area: Option<i64>,
    pub max_area: Option<i64>,
    pub min_written_pixels: Option<u64>,
    pub overlap: Option<(i32, i32, i32, i32)>,
}

impl NativeGpuDrawCapturePredicate {
    fn matches(&self, trace: &GpuDrawTrace) -> bool {
        if self
            .kind
            .as_ref()
            .is_some_and(|kind| trace.kind != kind.as_str())
        {
            return false;
        }
        if self.texture_page.is_some_and(|texture_page| {
            trace
                .texture_page
                .map(|trace_texture_page| trace_texture_page & GP0_POLYGON_TEXPAGE_MASK)
                != Some(texture_page & GP0_POLYGON_TEXPAGE_MASK)
        }) {
            return false;
        }
        if self.clut.is_some_and(|clut| trace.clut != Some(clut)) {
            return false;
        }
        let area = trace.bounds.area();
        if self.min_area.is_some_and(|min_area| area < min_area) {
            return false;
        }
        if self.max_area.is_some_and(|max_area| area > max_area) {
            return false;
        }
        if self
            .min_written_pixels
            .is_some_and(|min_written_pixels| trace.stats.written_pixels < min_written_pixels)
        {
            return false;
        }
        if let Some((left, top, right, bottom)) = self.overlap
            && !trace.bounds.overlaps(DrawBounds {
                left,
                top,
                right,
                bottom,
            })
        {
            return false;
        }
        true
    }

    pub fn json(&self) -> String {
        let overlap = self.overlap.map_or_else(
            || "null".to_string(),
            |(left, top, right, bottom)| {
                format!(
                    "{{\"left\":{},\"top\":{},\"right\":{},\"bottom\":{}}}",
                    left, top, right, bottom
                )
            },
        );
        format!(
            "{{\"kind\":{},\"texture_page\":{},\"texture_page_hex\":{},\"clut\":{},\"clut_hex\":{},\"min_area\":{},\"max_area\":{},\"min_written_pixels\":{},\"overlap\":{}}}",
            optional_str_json(self.kind.as_deref()),
            optional_u16_json(self.texture_page),
            optional_u16_hex_json(self.texture_page),
            optional_u16_json(self.clut),
            optional_u16_hex_json(self.clut),
            optional_i64_json(self.min_area),
            optional_i64_json(self.max_area),
            optional_u64_json(self.min_written_pixels),
            overlap
        )
    }
}

impl NativeGpuDrawCapture {
    pub fn json(
        &self,
        display_output: &str,
        actual_display_output: &str,
        raw_actual_display_output: &str,
        gui_display_output: &str,
        bounds_output: &str,
        texture_output: Option<&str>,
        raw_texture_output: Option<&str>,
        palette_output: Option<&str>,
        resolved_palette_output: Option<&str>,
        texture_candidate_outputs_json: &str,
    ) -> String {
        format!(
            "{{\"sequence\":{},\"display_output\":\"{}\",\"actual_display_output\":\"{}\",\"raw_actual_display_output\":\"{}\",\"gui_display_output\":\"{}\",\"bounds_output\":\"{}\",\"texture_output\":{},\"raw_texture_output\":{},\"palette_output\":{},\"resolved_palette_output\":{},\"texture_candidate_outputs\":[{}],\"display_window\":{{\"x\":{},\"y\":{},\"width\":{},\"height\":{}}},\"bounds_window\":{{\"x\":{},\"y\":{},\"width\":{},\"height\":{}}},\"texture_diagnostics\":{},\"trace\":{}}}",
            self.sequence,
            escape_json(display_output),
            escape_json(actual_display_output),
            escape_json(raw_actual_display_output),
            escape_json(gui_display_output),
            escape_json(bounds_output),
            optional_str_json(texture_output),
            optional_str_json(raw_texture_output),
            optional_str_json(palette_output),
            optional_str_json(resolved_palette_output),
            texture_candidate_outputs_json,
            self.display_x,
            self.display_y,
            self.display_width,
            self.display_height,
            self.bounds_x,
            self.bounds_y,
            self.bounds_width,
            self.bounds_height,
            optional_raw_json(self.texture_diagnostics_json.as_deref()),
            self.trace_json
        )
    }
}

