impl GpuTransferTrace {
    fn image_upload(
        dest_x: i32,
        dest_y: i32,
        width: i32,
        height: i32,
        data_words: usize,
        valid: bool,
        payload: GpuTransferPayloadStats,
        command_words: &[u32],
        source: Option<&GpuCommandSource>,
    ) -> Self {
        Self {
            sequence: 0,
            command_order: 0,
            vblank: 0,
            kind: "image_upload",
            source_x: None,
            source_y: None,
            dest_x,
            dest_y,
            width,
            height,
            data_words,
            valid,
            source_before: None,
            dest_before: None,
            dest_after: None,
            payload: Some(payload),
            command_words: command_words.iter().take(4).copied().collect(),
            source: source.cloned(),
        }
    }

    fn vram_copy(
        source_x: i32,
        source_y: i32,
        dest_x: i32,
        dest_y: i32,
        width: i32,
        height: i32,
        valid: bool,
        source_before: GpuTransferRegionStats,
        dest_before: GpuTransferRegionStats,
        dest_after: GpuTransferRegionStats,
        command_words: &[u32],
        source: Option<&GpuCommandSource>,
    ) -> Self {
        Self {
            sequence: 0,
            command_order: 0,
            vblank: 0,
            kind: "vram_copy",
            source_x: Some(source_x),
            source_y: Some(source_y),
            dest_x,
            dest_y,
            width,
            height,
            data_words: 0,
            valid,
            source_before: Some(source_before),
            dest_before: Some(dest_before),
            dest_after: Some(dest_after),
            payload: None,
            command_words: command_words.iter().take(4).copied().collect(),
            source: source.cloned(),
        }
    }

    fn json(&self) -> String {
        format!(
            "{{\"sequence\":{},\"command_order\":{},\"vblank\":{},\"kind\":\"{}\",\"source_rect\":{},\"dest_rect\":{},\"source_x\":{},\"source_y\":{},\"dest_x\":{},\"dest_y\":{},\"width\":{},\"height\":{},\"data_words\":{},\"valid\":{},\"source_before\":{},\"dest_before\":{},\"dest_after\":{},\"payload\":{},\"command_words\":[{}],\"command_source\":{}}}",
            self.sequence,
            self.command_order,
            self.vblank,
            self.kind,
            self.source_rect_json(),
            self.dest_rect_json(),
            optional_i32_json(self.source_x),
            optional_i32_json(self.source_y),
            self.dest_x,
            self.dest_y,
            self.width,
            self.height,
            self.data_words,
            self.valid,
            self.source_before
                .map_or_else(|| "null".to_string(), GpuTransferRegionStats::json),
            self.dest_before
                .map_or_else(|| "null".to_string(), GpuTransferRegionStats::json),
            self.dest_after
                .map_or_else(|| "null".to_string(), GpuTransferRegionStats::json),
            self.payload
                .map_or_else(|| "null".to_string(), GpuTransferPayloadStats::json),
            words_json(&self.command_words),
            optional_gpu_source_json(self.source.as_ref())
        )
    }

    fn dest_bounds(&self) -> DrawBounds {
        rect_bounds(
            Point {
                x: self.dest_x,
                y: self.dest_y,
            },
            self.width,
            self.height,
        )
    }

    fn source_bounds(&self) -> Option<DrawBounds> {
        self.source_x
            .zip(self.source_y)
            .map(|(x, y)| rect_bounds(Point { x, y }, self.width, self.height))
    }

    fn dest_overlap_area(&self, bounds: DrawBounds) -> i64 {
        transfer_overlap_area(self.dest_bounds(), bounds)
    }

    fn source_overlap_area(&self, bounds: DrawBounds) -> i64 {
        self.source_bounds()
            .map_or(0, |source| transfer_overlap_area(source, bounds))
    }

    fn dest_rect_json(&self) -> String {
        transfer_rect_json(self.dest_x, self.dest_y, self.width, self.height)
    }

    fn source_rect_json(&self) -> String {
        self.source_x.zip(self.source_y).map_or_else(
            || "null".to_string(),
            |(x, y)| transfer_rect_json(x, y, self.width, self.height),
        )
    }

    fn overlap_summary_json(&self, bounds: DrawBounds) -> String {
        let dest_overlap_area = self.dest_overlap_area(bounds);
        let source_overlap_area = self.source_overlap_area(bounds);
        format!(
            "{{\"bounds\":{},\"dest_overlap_area\":{},\"source_overlap_area\":{},\"transfer\":{}}}",
            bounds.json(),
            dest_overlap_area,
            source_overlap_area,
            self.json()
        )
    }
}

fn gpu_transfer_region_stats(
    framebuffer: &NativeFrameBuffer,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
) -> GpuTransferRegionStats {
    if width <= 0 || height <= 0 {
        return GpuTransferRegionStats::default();
    }

    let mut stats = GpuTransferRegionStats {
        pixels: (width as usize).saturating_mul(height as usize),
        checksum: 2_166_136_261,
        ..GpuTransferRegionStats::default()
    };
    let mut unique = Vec::<u16>::new();
    for row in 0..height {
        for column in 0..width {
            let color = framebuffer.raw_pixel(
                wrap_vram_coordinate(x + column, VRAM_WIDTH),
                wrap_vram_coordinate(y + row, PSX_VRAM_HEIGHT),
            );
            stats.checksum ^= u32::from(color);
            stats.checksum = stats.checksum.wrapping_mul(16_777_619);
            if color != 0 {
                stats.nonzero_pixels = stats.nonzero_pixels.saturating_add(1);
            }
            if unique.len() < 256 && !unique.contains(&color) {
                unique.push(color);
            }
        }
    }
    stats.unique_colors = unique.len();
    stats
}

fn texture_raw_bounds_for_trace(trace: &GpuDrawTrace) -> Option<DrawBounds> {
    let texture_page = trace.texture_page?;
    let (origin_x, origin_y) = trace.clut.map_or_else(
        || texture_page_origin_for_diagnostics(texture_page),
        |clut| texture_page_origin_for_clut_for_diagnostics(texture_page, clut),
    );
    let Some((min_u, min_v, max_u, max_v)) = texture_uv_bounds_for_trace(trace) else {
        return Some(rect_bounds(
            Point {
                x: origin_x,
                y: origin_y,
            },
            texture_raw_width_for_diagnostics(texture_page),
            256,
        ));
    };
    let mode = texture_page_color_mode_for_diagnostics(texture_page);
    let left = origin_x.saturating_add(texture_u_to_raw_word(mode, min_u));
    let right = origin_x.saturating_add(texture_u_to_raw_word(mode, max_u));
    Some(DrawBounds {
        left,
        top: origin_y.saturating_add(i32::from(min_v)),
        right,
        bottom: origin_y.saturating_add(i32::from(max_v)),
    })
}

fn texture_uv_bounds_for_trace(trace: &GpuDrawTrace) -> Option<(u8, u8, u8, u8)> {
    let first = *trace.uvs.first()?;
    if trace.kind == "textured_rect" {
        let width = trace.bounds.right.saturating_sub(trace.bounds.left).max(0) as u16;
        let height = trace.bounds.bottom.saturating_sub(trace.bounds.top).max(0) as u16;
        return Some((
            first.u,
            first.v,
            first.u.saturating_add(width.min(u16::from(u8::MAX)) as u8),
            first.v.saturating_add(height.min(u16::from(u8::MAX)) as u8),
        ));
    }

    let mut min_u = first.u;
    let mut min_v = first.v;
    let mut max_u = first.u;
    let mut max_v = first.v;
    for uv in &trace.uvs {
        min_u = min_u.min(uv.u);
        min_v = min_v.min(uv.v);
        max_u = max_u.max(uv.u);
        max_v = max_v.max(uv.v);
    }
    Some((min_u, min_v, max_u, max_v))
}

fn clut_bounds_for_trace(trace: &GpuDrawTrace) -> Option<DrawBounds> {
    let texture_page = trace.texture_page?;
    let clut = trace.clut?;
    let entries = texture_palette_entries_for_diagnostics(texture_page)?;
    let (x, y) = clut_origin_for_diagnostics(clut);
    Some(rect_bounds(Point { x, y }, entries, 1))
}

fn texture_raw_width_for_diagnostics(texture_page: u16) -> i32 {
    match texture_page_color_mode_for_diagnostics(texture_page) {
        0 => 64,
        1 => 128,
        _ => 256,
    }
}

fn texture_palette_entries_for_diagnostics(texture_page: u16) -> Option<i32> {
    match texture_page_color_mode_for_diagnostics(texture_page) {
        0 => Some(16),
        1 => Some(256),
        _ => None,
    }
}

fn texture_u_to_raw_word(mode: u16, u: u8) -> i32 {
    match mode {
        0 => i32::from(u) / 4,
        1 => i32::from(u) / 2,
        _ => i32::from(u),
    }
}

fn transfer_overlap_area(transfer_bounds: DrawBounds, target_bounds: DrawBounds) -> i64 {
    if transfer_bounds.left > transfer_bounds.right || transfer_bounds.top > transfer_bounds.bottom
    {
        return 0;
    }
    transfer_bounds.intersection_area(target_bounds)
}

fn transfer_rect_json(x: i32, y: i32, width: i32, height: i32) -> String {
    let bounds = rect_bounds(Point { x, y }, width, height);
    format!(
        "{{\"x\":{},\"y\":{},\"width\":{},\"height\":{},\"bounds\":{}}}",
        x,
        y,
        width,
        height,
        bounds.json()
    )
}

fn gpu_transfer_payload_stats(words: &[u32]) -> GpuTransferPayloadStats {
    let mut stats = GpuTransferPayloadStats {
        words: words.len(),
        halfwords: words.len().saturating_mul(2),
        checksum: 2_166_136_261,
        ..GpuTransferPayloadStats::default()
    };
    let mut unique = Vec::<u16>::new();
    for word in words {
        for color in [*word as u16, (*word >> 16) as u16] {
            stats.checksum ^= u32::from(color);
            stats.checksum = stats.checksum.wrapping_mul(16_777_619);
            if color != 0 {
                stats.nonzero_halfwords = stats.nonzero_halfwords.saturating_add(1);
            }
            if unique.len() < 256 && !unique.contains(&color) {
                unique.push(color);
            }
        }
    }
    stats.unique_colors = unique.len();
    stats
}

fn wrap_vram_coordinate(value: i32, extent: usize) -> i32 {
    value.rem_euclid(extent as i32)
}

fn gp0_expected_words(fifo: &[u32]) -> Option<usize> {
    let first = *fifo.first()?;
    let command = (first >> 24) as u8;
    let expected = match command {
        0x00 | 0x01 | 0x03..=0x1f | 0xe1..=0xe6 => 1,
        0x02 => 3,
        0x20..=0x23 => 4,
        0x24..=0x27 => 7,
        0x28..=0x2b => 5,
        0x2c..=0x2f => 9,
        0x30..=0x33 => 6,
        0x34..=0x37 => 9,
        0x38..=0x3b => 8,
        0x3c..=0x3f => 12,
        0x40..=0x47 => 3,
        0x48..=0x4f => polyline_words(fifo)?,
        0x50..=0x57 => 4,
        0x58..=0x5f => polyline_words(fifo)?,
        0x60..=0x63 => 3,
        0x64..=0x67 => 4,
        0x68..=0x6f => 2,
        0x70..=0x73 => 2,
        0x74..=0x77 => 3,
        0x78..=0x7b => 2,
        0x7c..=0x7f => 3,
        0x80..=0x9f => 4,
        0xa0..=0xbf => image_transfer_words(fifo)?,
        0xc0..=0xdf => 3,
        _ => 1,
    };
    Some(expected)
}

fn gp0_command_may_update_framebuffer(command: u8) -> bool {
    matches!(command, 0x02 | 0x20..=0xbf)
}

pub(crate) fn gp0_command_word_count(fifo: &[u32]) -> Option<usize> {
    gp0_expected_words(fifo)
}

fn polyline_words(fifo: &[u32]) -> Option<usize> {
    fifo.iter()
        .position(|word| *word == 0x5555_5555)
        .map(|index| index + 1)
        .or_else(|| (fifo.len() > 256).then_some(fifo.len()))
}

fn image_transfer_words(fifo: &[u32]) -> Option<usize> {
    if fifo.len() < 3 {
        return Some(3);
    }

    let Some((width, height)) = image_transfer_dimensions(fifo[2]) else {
        // Consume the complete transfer header so a malformed size cannot
        // leave its coordinate/size words queued as unrelated GP0 commands.
        return Some(3);
    };
    let pixels = width.saturating_mul(height);
    Some(3 + pixels.div_ceil(2) as usize)
}

fn image_transfer_dimensions(value: u32) -> Option<(u32, u32)> {
    let width = gpu_transfer_extent(value & 0xffff, 0x03ff);
    let height = gpu_transfer_extent((value >> 16) & 0xffff, 0x01ff);
    Some((width, height))
}

fn gpu_transfer_extent(raw: u32, mask: u32) -> u32 {
    (raw.wrapping_sub(1) & mask) + 1
}

fn display_area_start_xy(value: u32) -> (usize, usize) {
    let x = (value & VRAM_X_MASK) as usize;
    let y = ((value >> 10) & VRAM_Y_MASK) as usize;
    (x.min(VRAM_WIDTH - 1), y.min(VRAM_HEIGHT - 1))
}

fn display_dimensions_from_registers(
    status: u32,
    horizontal_range: u32,
    vertical_range: u32,
) -> (usize, usize) {
    let (status_width, status_height) = display_dimensions_from_status(status);
    let width = display_width_from_horizontal_range(status_width, horizontal_range);
    let height = display_height_from_vertical_range(status, status_height, vertical_range);
    (width, height)
}

fn display_dimensions_from_status(status: u32) -> (usize, usize) {
    let width = match (status >> 17) & 0x03 {
        0 => 256,
        1 => 320,
        2 => 512,
        _ => 640,
    };
    let high_vertical_resolution = status & (1 << 19) != 0 && status & (1 << 22) != 0;
    let height = if high_vertical_resolution { 480 } else { 240 };
    (width.min(VRAM_WIDTH), height.min(VRAM_HEIGHT))
}

fn display_width_from_horizontal_range(status_width: usize, horizontal_range: u32) -> usize {
    let start = horizontal_range & 0x0fff;
    let end = (horizontal_range >> 12) & 0x0fff;
    if end <= start {
        return status_width.min(VRAM_WIDTH);
    }

    let dots = end - start;
    let dot_divider = match status_width {
        256 => 10,
        320 => 8,
        512 => 5,
        640 => 4,
        _ => 1,
    };
    let ranged_width = (dots / dot_divider).max(1) as usize;
    ranged_width.min(status_width).min(VRAM_WIDTH)
}

fn display_height_from_vertical_range(
    status: u32,
    status_height: usize,
    vertical_range: u32,
) -> usize {
    let start = vertical_range & 0x03ff;
    let end = (vertical_range >> 10) & 0x03ff;
    if end <= start {
        return status_height.min(VRAM_HEIGHT);
    }

    let ranged_height = (end - start).max(1) as usize;
    if high_vertical_resolution_status(status)
        && status_height >= DEFAULT_DISPLAY_HEIGHT * 2
        && ranged_height <= status_height / 2
    {
        return ranged_height
            .saturating_mul(2)
            .min(status_height)
            .min(VRAM_HEIGHT);
    }

    ranged_height.min(status_height).min(VRAM_HEIGHT)
}

fn high_vertical_resolution_status(status: u32) -> bool {
    status & (1 << 19) != 0 && status & (1 << 22) != 0
}

fn xy(value: u32) -> (i32, i32) {
    (
        sign_extend_11(value & 0x07ff),
        sign_extend_11((value >> 16) & 0x07ff),
    )
}

fn unsigned_xy(value: u32) -> (i32, i32) {
    (
        (value & VRAM_X_MASK).min((VRAM_WIDTH - 1) as u32) as i32,
        ((value >> 16) & VRAM_Y_MASK).min((VRAM_HEIGHT - 1) as u32) as i32,
    )
}

fn points_bounds(points: &[Point]) -> DrawBounds {
    let mut left = i32::MAX;
    let mut top = i32::MAX;
    let mut right = i32::MIN;
    let mut bottom = i32::MIN;
    for point in points {
        left = left.min(point.x);
        top = top.min(point.y);
        right = right.max(point.x);
        bottom = bottom.max(point.y);
    }
    DrawBounds {
        left,
        top,
        right,
        bottom,
    }
}

fn rect_bounds(point: Point, width: i32, height: i32) -> DrawBounds {
    DrawBounds {
        left: point.x,
        top: point.y,
        right: point.x.saturating_add(width).saturating_sub(1),
        bottom: point.y.saturating_add(height).saturating_sub(1),
    }
}

fn combine_textured_draw_stats(
    first: TexturedDrawStats,
    second: TexturedDrawStats,
) -> TexturedDrawStats {
    TexturedDrawStats {
        sampled_pixels: first.sampled_pixels.saturating_add(second.sampled_pixels),
        drawn_pixels: first.drawn_pixels.saturating_add(second.drawn_pixels),
        written_pixels: first.written_pixels.saturating_add(second.written_pixels),
        clipped_pixels: first.clipped_pixels.saturating_add(second.clipped_pixels),
        transparent_pixels: first
            .transparent_pixels
            .saturating_add(second.transparent_pixels),
        texture_nonzero_samples: first
            .texture_nonzero_samples
            .saturating_add(second.texture_nonzero_samples),
        zero_texel_samples: first
            .zero_texel_samples
            .saturating_add(second.zero_texel_samples),
        clut_nonzero_samples: first
            .clut_nonzero_samples
            .saturating_add(second.clut_nonzero_samples),
        clut_blank_samples: first
            .clut_blank_samples
            .saturating_add(second.clut_blank_samples),
        palette_fallback_samples: first
            .palette_fallback_samples
            .saturating_add(second.palette_fallback_samples),
        nonzero_texel_transparent_samples: first
            .nonzero_texel_transparent_samples
            .saturating_add(second.nonzero_texel_transparent_samples),
        first_color: if first.drawn_pixels != 0 {
            first.first_color
        } else {
            second.first_color
        },
        last_color: if second.drawn_pixels != 0 {
            second.last_color
        } else {
            first.last_color
        },
        color_hash: first
            .color_hash
            .wrapping_mul(16_777_619)
            .wrapping_add(second.color_hash),
        color_changes: first
            .color_changes
            .saturating_add(second.color_changes)
            .saturating_add(u64::from(
                first.drawn_pixels != 0
                    && second.drawn_pixels != 0
                    && first.last_color != second.first_color,
            )),
    }
}

fn first_command_source(sources: &[Option<GpuCommandSource>]) -> Option<GpuCommandSource> {
    sources.first().and_then(Clone::clone)
}

fn fill_rect_dimensions_valid(width: i32, height: i32) -> bool {
    width > 0 && height > 0 && width <= VRAM_WIDTH as i32 && height <= VRAM_HEIGHT as i32
}

fn vram_copy_dimensions_valid(width: i32, height: i32) -> bool {
    width > 0 && height > 0 && width <= VRAM_WIDTH as i32 && height <= PSX_VRAM_HEIGHT as i32
}

fn vram_copy_dimensions(value: u32) -> Option<(i32, i32)> {
    let width = gpu_transfer_extent(value & 0xffff, 0x03ff);
    let height = gpu_transfer_extent((value >> 16) & 0xffff, 0x01ff);
    Some((width as i32, height as i32))
}

fn vram_copy_request_valid(
    _source_x: i32,
    _source_y: i32,
    _dest_x: i32,
    _dest_y: i32,
    width: i32,
    height: i32,
) -> bool {
    if !vram_copy_dimensions_valid(width, height) {
        return false;
    }

    true
}

fn should_preserve_br2_populated_palette_on_blank_copy(
    source_x: i32,
    source_y: i32,
    dest_x: i32,
    dest_y: i32,
    width: i32,
    height: i32,
    source_before: GpuTransferRegionStats,
    dest_before: GpuTransferRegionStats,
    source: Option<&GpuCommandSource>,
) -> bool {
    should_preserve_br2_populated_palette_on_blank_copy_with_policy(
        source_x,
        source_y,
        dest_x,
        dest_y,
        width,
        height,
        source_before,
        dest_before,
        source,
        native_preserve_br2_populated_palette_on_blank_copy(),
    )
}

fn should_preserve_br2_populated_palette_on_blank_copy_with_policy(
    source_x: i32,
    source_y: i32,
    dest_x: i32,
    dest_y: i32,
    width: i32,
    height: i32,
    source_before: GpuTransferRegionStats,
    dest_before: GpuTransferRegionStats,
    source: Option<&GpuCommandSource>,
    enabled: bool,
) -> bool {
    if !enabled {
        return false;
    }

    source.is_some_and(GpuCommandSource::is_dma_linked_list)
        && source_x == dest_x
        && matches!(source_x, 0 | 48)
        && source_y == 496
        && dest_y == 480
        && width == 32
        && height == 16
        && source_before.pixels == 512
        && source_before.nonzero_pixels == 0
        && dest_before.nonzero_pixels >= 480
        && dest_before.unique_colors >= 64
}

fn raw_dimensions(value: u32) -> (u32, u32) {
    (value & 0xffff, (value >> 16) & 0xffff)
}

fn drawing_offset_xy(value: u32) -> (i32, i32) {
    (
        sign_extend_11(value & 0x07ff),
        sign_extend_11((value >> 11) & 0x07ff),
    )
}

fn drawing_area_xy(value: u32) -> (i32, i32) {
    (
        (value & VRAM_X_MASK).min((VRAM_WIDTH - 1) as u32) as i32,
        ((value >> 10) & VRAM_Y_MASK).min((VRAM_HEIGHT - 1) as u32) as i32,
    )
}

fn drawing_area_clip(top_left: u32, bottom_right: u32) -> Option<ClipRect> {
    let (left, top) = drawing_area_xy(top_left);
    let (right, bottom) = drawing_area_xy(bottom_right);
    ClipRect::new(left, top, right, bottom)
}

fn draw_bounds_clip_intersection_area(bounds: DrawBounds, clip: ClipRect) -> i64 {
    bounds.intersection_area(DrawBounds {
        left: clip.left,
        top: clip.top,
        right: clip.right,
        bottom: clip.bottom,
    })
}

fn point(value: u32) -> Point {
    let (x, y) = xy(value);
    Point { x, y }
}

fn sign_extend_11(value: u32) -> i32 {
    let value = value & 0x07ff;
    if value & 0x0400 != 0 {
        (value | !0x07ff) as i32
    } else {
        value as i32
    }
}

fn color(value: u32) -> u32 {
    let r = value & 0xff;
    let g = (value >> 8) & 0xff;
    let b = (value >> 16) & 0xff;
    (r << 16) | (g << 8) | b
}

fn command_color(value: u32) -> u32 {
    value & 0x00ff_ffff
}

fn clut(value: u32) -> u16 {
    (value >> 16) as u16
}

fn texture_page(value: u32) -> u16 {
    (value >> 16) as u16
}

fn texture_draw_options(command_word: u32, texture_page: u16) -> TextureDrawOptions {
    let command = (command_word >> 24) as u8;
    let allow_sprite_flip = matches!(command, 0x64..=0x7f);
    let allow_palette_fallback = !matches!(command, 0x24..=0x3f)
        && !zn_low_bank_title_rect_palette_fallback_is_risky(command, texture_page);
    TextureDrawOptions {
        primitive_color: command_word & 0x00ff_ffff,
        // GP0 textured primitive opcodes use bit 0 for raw texture and bit 1
        // for semi-transparency (0x24/25/26/27 and equivalent families).
        raw_texture: command & 0x01 != 0,
        semi_transparent: command & 0x02 != 0,
        semi_transparency_mode: ((texture_page >> 5) & 0x03) as u8,
        set_mask_bit: false,
        check_mask_bit: false,
        texture_flip_x: allow_sprite_flip && texture_page & 0x1000 != 0,
        texture_flip_y: allow_sprite_flip && texture_page & 0x2000 != 0,
        allow_palette_fallback,
        allow_texture_descriptor_alias: true,
    }
}

fn zn_low_bank_title_rect_palette_fallback_is_risky(command: u8, texture_page: u16) -> bool {
    let texture_mode = (texture_page >> 7) & 0x03;
    matches!(command, 0x64..=0x7f)
        && texture_mode == 1
        && texture_page & 0x0200 != 0
        && texture_page & 0x0010 != 0
        && texture_page & 0x0800 == 0
        && texture_page & 0x2000 == 0
}

fn should_allow_br2_character_select_polygon_palette_fallback(
    command_word: u32,
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    let command = (command_word >> 24) as u8;
    let descriptor = texture_page & !0x0200;
    matches!(command, 0x2c..=0x2f | 0x3c..=0x3f)
        && matches!(
            (descriptor, clut),
            (0x0088, 0x7d40) | (0x0088, 0x7d80) | (0x008a, 0x7d80)
        )
        && bounds.area() >= 8_000
        && bounds.top <= 180
        && bounds.bottom >= 300
}

fn should_allow_br2_gameplay_polygon_palette_fallback(
    command_word: u32,
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    if native_disable_br2_gameplay_palette_fallback() {
        return false;
    }
    let command = (command_word >> 24) as u8;
    let low_bank_descriptor =
        br2_low_bank_gameplay_character_texture_descriptor(texture_page, clut);
    let descriptor = texture_page & !0x0200;
    let clut_x = (clut & 0x3f) as usize * 16;
    let clut_y = clut_row(clut);
    // BR2 character bodies are submitted as many small polygons. Their requested
    // CLUT row at x=64 is blank, so these captured body descriptors must enable
    // the framebuffer's neutral material fallback even when the polygons are
    // too small for the general low-bank recovery guard.
    let small_gameplay_body =
        matches!(descriptor, 0x000c | 0x000d) && clut_x == 64 && (480..=486).contains(&clut_y);
    let small_yugo_fighter = descriptor == 0x000b && clut_x == 48 && matches!(clut_y, 480 | 484);
    let small_low_bank_fighter =
        (0x0008..=0x000e).contains(&descriptor) && clut_x <= 64 && (480..512).contains(&clut_y);
    let low_bank_character = low_bank_descriptor
        && (small_gameplay_body
            || small_yugo_fighter
            || small_low_bank_fighter
            || bounds.area() >= 1_024);
    matches!(command, 0x24..=0x2f | 0x34..=0x3f)
        && (matches!((texture_page, clut), (0x002e, 0x7b9e))
            || (br2_reused_texture_page_0039(texture_page)
                && matches!(clut, 0x799a | 0x79d9 | 0x7a5a | 0x7a9a))
            || low_bank_character)
        && bounds.left <= 511
        && bounds.right >= 0
        && bounds.top <= 479
        && bounds.bottom >= 0
        && bounds.area() <= 32_768
}

fn br2_low_bank_gameplay_character_texture_descriptor(texture_page: u16, clut: u16) -> bool {
    let texture_page = texture_page & !0x0200;
    ((texture_page >> 7) & 0x03) == 0
        && (0x0008..=0x000e).contains(&texture_page)
        && (480..512).contains(&clut_row(clut))
        && (clut & 0x3f) < 63
}

fn br2_reused_texture_page_0039(texture_page: u16) -> bool {
    texture_page & !0x0200 == 0x0039
}

fn should_allow_zn_low_bank_screen_rect_palette_fallback(
    command_word: u32,
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    let command = (command_word >> 24) as u8;
    if !matches!(command, 0x64..=0x67)
        || !zn_low_bank_title_rect_palette_fallback_is_risky(command, texture_page)
    {
        return false;
    }

    let clut_row = clut_row(clut);
    if !(480..512).contains(&clut_row) {
        return false;
    }

    let width = bounds.right.saturating_sub(bounds.left).saturating_add(1);
    let height = bounds.bottom.saturating_sub(bounds.top).saturating_add(1);
    is_zn_screen_quadrant_rect(bounds, width, height)
}

fn should_disable_zn_low_bank_4bpp_screen_rect_palette_fallback(
    command_word: u32,
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    let command = (command_word >> 24) as u8;
    let texture_mode = (texture_page >> 7) & 0x03;
    if !matches!(command, 0x64..=0x67) || texture_mode != 0 {
        return false;
    }

    let clut_row = clut_row(clut);
    if !(480..512).contains(&clut_row) {
        return false;
    }

    let width = bounds.right.saturating_sub(bounds.left).saturating_add(1);
    let height = bounds.bottom.saturating_sub(bounds.top).saturating_add(1);
    is_zn_screen_quadrant_rect(bounds, width, height)
}

fn should_disable_br2_blank_clut_screen_rect_palette_fallback(
    command_word: u32,
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    let command = (command_word >> 24) as u8;
    if !matches!(command, 0x64..=0x67) || texture_page != 0x0288 || clut != 0x7c00 {
        return false;
    }

    let width = bounds.right.saturating_sub(bounds.left).saturating_add(1);
    let height = bounds.bottom.saturating_sub(bounds.top).saturating_add(1);
    is_zn_screen_quadrant_rect(bounds, width, height)
}

fn should_skip_noisy_4bpp_title_draw(texture_page: u16, clut: u16, bounds: DrawBounds) -> bool {
    let texture_mode = (texture_page >> 7) & 0x03;
    if texture_mode != 0 {
        return false;
    }

    if should_skip_low_bank_fullscreen_atlas_blit(texture_page, clut, bounds) {
        return true;
    }

    if !br2_reused_texture_page_0039(texture_page) {
        return false;
    }

    // BR2 reuses page 0x0039 for live character geometry. The corrupt title
    // primitive captured on this page uses CLUT 0x795a; matching the entire
    // 485..=501 row band also discards gameplay CLUTs such as 0x799a/0x79d9.
    let uses_corrupt_title_clut = clut == 0x795a;
    let visible_title_overlay = bounds.overlaps(DrawBounds {
        left: 0,
        top: 96,
        right: 511,
        bottom: 479,
    });

    uses_corrupt_title_clut && visible_title_overlay && bounds.right >= 128 && bounds.bottom >= 120
}

fn should_skip_br2_stale_character_select_stage_atlas_strip(
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
    points: &[TexturedPoint],
) -> bool {
    if native_disable_br2_stage_strip_skip() {
        return false;
    }

    if texture_page & !0x0200 != 0x000c || clut != 0x7d18 || points.len() != 4 {
        return false;
    }

    let width = bounds.right.saturating_sub(bounds.left).saturating_add(1);
    let height = bounds.bottom.saturating_sub(bounds.top).saturating_add(1);
    let horizontal_stage_strip = (240..=272).contains(&width)
        && (28..=40).contains(&height)
        && (88..=390).contains(&bounds.top)
        && (122..=426).contains(&bounds.bottom);
    let right_half = (248..=264).contains(&bounds.left) && (504..=520).contains(&bounds.right);
    if !horizontal_stage_strip || !right_half {
        return false;
    }

    let min_u = points.iter().map(|point| point.u).min().unwrap_or_default();
    let max_u = points.iter().map(|point| point.u).max().unwrap_or_default();
    let min_v = points.iter().map(|point| point.v).min().unwrap_or_default();
    let max_v = points.iter().map(|point| point.v).max().unwrap_or_default();
    let uses_captured_u_band = (min_u <= 1 && (63..=65).contains(&max_u))
        || ((63..=65).contains(&min_u) && (127..=129).contains(&max_u));
    let uses_captured_v_band = matches!((min_v, max_v), (32, 39) | (40, 47));

    uses_captured_u_band && uses_captured_v_band
}

fn native_disable_br2_stage_strip_skip() -> bool {
    static DISABLED: OnceLock<bool> = OnceLock::new();
    *DISABLED.get_or_init(|| {
        std::env::var("BLOODYROAR2_NATIVE_DISABLE_BR2_STAGE_STRIP_SKIP")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn native_disable_br2_gameplay_palette_fallback() -> bool {
    static DISABLED: OnceLock<bool> = OnceLock::new();
    *DISABLED.get_or_init(|| {
        std::env::var("BLOODYROAR2_NATIVE_DISABLE_BR2_GAMEPLAY_PALETTE_FALLBACK")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn native_preserve_br2_populated_palette_on_blank_copy() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BLOODYROAR2_NATIVE_PRESERVE_POPULATED_PALETTE_COPY")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn should_skip_low_bank_fullscreen_atlas_blit(
    texture_page: u16,
    clut: u16,
    bounds: DrawBounds,
) -> bool {
    if !matches!(texture_page, 0x002e | 0x002f | 0x003e | 0x003f)
        && !br2_reused_texture_page_0039(texture_page)
        || !matches!(clut, 0x7c40 | 0x7c80 | 0x7cc0)
    {
        return false;
    }

    let width = bounds.right.saturating_sub(bounds.left).saturating_add(1);
    let height = bounds.bottom.saturating_sub(bounds.top).saturating_add(1);
    is_zn_screen_quadrant_rect(bounds, width, height)
}

fn is_zn_screen_quadrant_rect(bounds: DrawBounds, width: i32, height: i32) -> bool {
    let covers_screen_quadrant = width >= 240
        && height >= 220
        && bounds.overlaps(DrawBounds {
            left: 0,
            top: 0,
            right: 511,
            bottom: 479,
        });

    covers_screen_quadrant && bounds.area() >= 50_000
}

fn clut_row(clut: u16) -> u16 {
    (clut >> 6) & 0x03ff
}

fn native_use_alternate_quad_split() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BLOODYROAR2_NATIVE_ALT_QUAD_SPLIT")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn native_disable_high_vertical_field_local_clip() -> bool {
    static DISABLED: OnceLock<bool> = OnceLock::new();
    *DISABLED.get_or_init(|| {
        std::env::var("BLOODYROAR2_NATIVE_DISABLE_HIGH_VERTICAL_FIELD_LOCAL_CLIP")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn texture_coordinate(value: u32) -> TextureCoordinate {
    TextureCoordinate {
        u: (value & 0xff) as u8,
        v: ((value >> 8) & 0xff) as u8,
    }
}

