fn framebuffer_window_json(window: FrameBufferWindow) -> String {
    format!(
        "{{\"x\":{},\"y\":{},\"pixel_count\":{},\"nonzero_pixels\":{},\"bright_pixels\":{},\"avg_luma\":{},\"max_luma\":{},\"detail_edges\":{},\"checksum\":{}}}",
        window.x,
        window.y,
        window.stats.pixel_count,
        window.stats.nonzero_pixels,
        window.stats.bright_pixels,
        average_luma(window.stats),
        window.stats.max_luma,
        window.stats.detail_edges,
        window.stats.checksum
    )
}

fn average_luma(stats: FrameBufferStats) -> u64 {
    stats.luma_sum.checked_div(stats.pixel_count).unwrap_or(0)
}

fn rgb_luma(rgb: u32) -> u8 {
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;
    ((red * 30 + green * 59 + blue * 11) / 100) as u8
}

fn rgb_framebuffer_stats(pixels: &[u32], width: usize, height: usize) -> FrameBufferStats {
    let pixel_count = (width as u64).saturating_mul(height as u64);
    let mut nonzero_pixels = 0_u64;
    let mut bright_pixels = 0_u64;
    let mut luma_sum = 0_u64;
    let mut max_luma = 0_u8;
    let mut detail_edges = 0_u64;
    let mut checksum = 0x811c_9dc5_u32;
    let mut previous_row_luma = vec![0_u8; width];

    for y in 0..height {
        let mut previous_luma = 0_u8;
        let row = y.saturating_mul(width);
        for x in 0..width {
            let rgb = pixels.get(row.saturating_add(x)).copied().unwrap_or(0) & 0x00ff_ffff;
            if rgb != 0 {
                nonzero_pixels = nonzero_pixels.saturating_add(1);
            }
            let luma = rgb_luma(rgb);
            if luma >= 32 {
                bright_pixels = bright_pixels.saturating_add(1);
            }
            luma_sum = luma_sum.saturating_add(u64::from(luma));
            max_luma = max_luma.max(luma);
            if x > 0 && luma.abs_diff(previous_luma) >= 16 {
                detail_edges = detail_edges.saturating_add(1);
            }
            if y > 0
                && previous_row_luma
                    .get(x)
                    .is_some_and(|previous| luma.abs_diff(*previous) >= 16)
            {
                detail_edges = detail_edges.saturating_add(1);
            }
            previous_luma = luma;
            if let Some(previous_row_luma) = previous_row_luma.get_mut(x) {
                *previous_row_luma = luma;
            }
            checksum ^= rgb;
            checksum = checksum.wrapping_mul(16_777_619);
        }
    }

    FrameBufferStats {
        pixel_count,
        nonzero_pixels,
        bright_pixels,
        luma_sum,
        max_luma,
        detail_edges,
        checksum,
    }
}

fn primitive_workspace_plane_color(rgb: u32) -> bool {
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;
    let max_channel = red.max(green).max(blue);
    let min_channel = red.min(green).min(blue);

    max_channel >= 192 && max_channel.saturating_sub(min_channel) >= 112
}

fn primitive_workspace_tear_color(rgb: u32) -> bool {
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;
    let max_channel = red.max(green).max(blue);
    let luma = (red * 30 + green * 59 + blue * 11) / 100;

    luma <= 32
        || (red >= 144 && green <= 96 && blue <= 128)
        || (red >= 144 && green <= 96 && blue >= 144)
        || (red <= 96 && green >= 144 && blue >= 144)
        || (max_channel >= 208 && red.max(blue).saturating_sub(green) >= 96)
}

fn primitive_workspace_dark_tear_color(rgb: u32) -> bool {
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;
    let luma = (red * 30 + green * 59 + blue * 11) / 100;

    luma <= 32
}

fn primitive_workspace_color_bucket(rgb: u32) -> u32 {
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;

    ((red >> 5) << 6) | ((green >> 5) << 3) | (blue >> 5)
}

fn screen_observation_worth_saving(stats: FrameBufferStats) -> bool {
    if is_low_information_observation(stats) {
        return false;
    }
    if stats.bright_pixels == 0 && average_luma(stats) < 8 {
        return false;
    }
    stats.bright_pixels >= 256 || stats.nonzero_pixels >= 2048 || stats.max_luma >= 64
}

fn screen_observation_score(stats: FrameBufferStats) -> u64 {
    let average_luma = average_luma(stats);
    let luma_contrast = u64::from(stats.max_luma).saturating_sub(average_luma);
    let almost_full = stats.nonzero_pixels >= stats.pixel_count.saturating_mul(120) / 128;
    let detail_cutoff = detail_edge_cutoff(stats);
    let low_detail_full_frame =
        almost_full && (luma_contrast < 48 || stats.detail_edges < detail_cutoff);
    let bright_weight = if low_detail_full_frame { 2 } else { 8 };

    stats
        .bright_pixels
        .saturating_mul(bright_weight)
        .saturating_add(stats.nonzero_pixels)
        .saturating_add(average_luma.saturating_mul(64))
        .saturating_add(luma_contrast.saturating_mul(4096))
        .saturating_add(stats.detail_edges.saturating_mul(64))
        .saturating_sub(if low_detail_full_frame {
            stats.pixel_count.saturating_mul(2)
        } else {
            0
        })
}

fn replay_window_has_catastrophic_regression(
    before: FrameBufferStats,
    candidate: FrameBufferStats,
) -> bool {
    if !screen_observation_worth_saving(before)
        || !is_detailed_observation(before)
        || before.nonzero_pixels < 2_048
        || before.detail_edges < 512
    {
        return false;
    }

    let before_score = screen_observation_score(before);
    let candidate_score = screen_observation_score(candidate);
    let score_collapsed = candidate_score.saturating_mul(4) < before_score.saturating_mul(3);
    let pixels_collapsed = candidate.nonzero_pixels.saturating_mul(2) < before.nonzero_pixels;
    let detail_collapsed = candidate.detail_edges.saturating_mul(2) < before.detail_edges;

    score_collapsed && (pixels_collapsed || detail_collapsed)
        || pixels_collapsed && detail_collapsed
}

fn minimum_live_draw_overlap_area_for_dimensions(width: usize, height: usize) -> i64 {
    ((width as i64).saturating_mul(height as i64) / 64).max(512)
}

fn is_detailed_observation(stats: FrameBufferStats) -> bool {
    !is_low_information_observation(stats)
        && stats.detail_edges >= detail_edge_cutoff(stats)
        && stats.max_luma >= 128
}

fn has_native_full_scene_detail(stats: FrameBufferStats) -> bool {
    has_native_playfield_density(stats)
        && is_detailed_observation(stats)
        && stats.detail_edges >= full_scene_detail_cutoff(stats)
}

fn has_native_gameplay_display_profile(stats: FrameBufferStats) -> bool {
    stats.pixel_count > 0
        && has_native_full_scene_detail(stats)
        && stats.nonzero_pixels.saturating_mul(100) >= stats.pixel_count.saturating_mul(65)
        && average_luma(stats) >= 12
}

fn has_native_playfield_density(stats: FrameBufferStats) -> bool {
    stats.nonzero_pixels >= stats.pixel_count.saturating_mul(3) / 10
        && stats.bright_pixels >= stats.pixel_count.saturating_div(64).max(512)
}

fn presented_frame_has_live_scene(stats: FrameBufferStats) -> bool {
    has_native_playfield_density(stats) && is_detailed_observation(stats)
}

fn detail_edge_cutoff(stats: FrameBufferStats) -> u64 {
    (stats.pixel_count / 64).max(256)
}

fn full_scene_detail_cutoff(stats: FrameBufferStats) -> u64 {
    (stats.pixel_count / 32).max(2048)
}

fn is_low_information_observation(stats: FrameBufferStats) -> bool {
    let nearly_all_pixels = stats
        .pixel_count
        .saturating_sub(stats.pixel_count / 128)
        .max(1);
    let average_luma = average_luma(stats);
    let nearly_uniform_luma =
        stats.nonzero_pixels >= nearly_all_pixels && u64::from(stats.max_luma) <= average_luma + 2;
    let nearly_solid_bright =
        stats.nonzero_pixels >= nearly_all_pixels && stats.bright_pixels >= nearly_all_pixels;

    nearly_uniform_luma || (nearly_solid_bright && average_luma >= 248)
}

fn should_use_observation_fallback(
    display_stats: FrameBufferStats,
    candidate_stats: FrameBufferStats,
) -> bool {
    if candidate_stats.bright_pixels == 0 {
        return false;
    }

    let sparse_nonzero = is_sparse_display(display_stats)
        && candidate_stats.nonzero_pixels > display_stats.nonzero_pixels.saturating_mul(4);
    let dark_display = display_stats.bright_pixels < (display_stats.pixel_count / 256).max(1)
        && candidate_stats.bright_pixels > display_stats.bright_pixels.saturating_mul(4).max(64);
    let brighter_candidate = average_luma(candidate_stats) >= average_luma(display_stats) + 8
        && candidate_stats.bright_pixels > display_stats.bright_pixels.saturating_mul(2).max(256);

    sparse_nonzero || dark_display || brighter_candidate
}

fn should_defer_low_detail_current(
    current_stats: FrameBufferStats,
    candidate_stats: FrameBufferStats,
) -> bool {
    if !is_detailed_observation(candidate_stats) {
        return false;
    }

    let current_score = screen_observation_score(current_stats);
    let candidate_score = screen_observation_score(candidate_stats);
    let much_more_detail =
        candidate_stats.detail_edges > current_stats.detail_edges.saturating_mul(4).max(512);
    if !much_more_detail {
        return false;
    }
    if candidate_score > current_score.saturating_mul(2) {
        return true;
    }

    has_native_full_scene_detail(candidate_stats)
        && candidate_score > current_score.saturating_add(current_score / 2)
}

fn resolved_display_candidate_has_scene_signal(
    current: FrameBufferWindow,
    current_score: u64,
    candidate: FrameBufferWindow,
) -> bool {
    if candidate.x == current.x
        && candidate.y == current.y
        && candidate.stats.checksum == current.stats.checksum
    {
        return false;
    }
    if !has_native_playfield_density(candidate.stats) || !is_detailed_observation(candidate.stats) {
        return false;
    }

    let candidate_score = screen_observation_score(candidate.stats);
    candidate_score > current_score.saturating_add(current_score / 2)
        && candidate.stats.detail_edges > current.stats.detail_edges.saturating_mul(4).max(512)
}

fn is_sparse_display(display_stats: FrameBufferStats) -> bool {
    let sparse_display_cutoff = (DEFAULT_DISPLAY_WIDTH * DEFAULT_DISPLAY_HEIGHT / 64) as u64;
    display_stats.nonzero_pixels < sparse_display_cutoff
}

fn high_vertical_single_field_is_sparse(stats: FrameBufferStats) -> bool {
    let pixel_count = stats.pixel_count.max(1);
    stats.nonzero_pixels < pixel_count / 128
        || (stats.bright_pixels < pixel_count / 512 && average_luma(stats) < 4)
}

fn is_likely_texture_page_origin(x: usize, y: usize) -> bool {
    matches!(x, 0 | 320 | 512 | 640) && matches!(y, 0 | 240 | 480 | PSX_VRAM_HEIGHT)
}

fn is_likely_texture_page_candidate(x: usize, y: usize, width: usize, height: usize) -> bool {
    if is_likely_texture_page_origin(x, y) {
        return true;
    }

    let right = x.saturating_add(width);
    let bottom = y.saturating_add(height);
    let starts_in_texture_column = matches!(x, 512 | 640);
    let is_large_page = width >= DEFAULT_DISPLAY_WIDTH && height >= DEFAULT_DISPLAY_HEIGHT;
    starts_in_texture_column && is_large_page && right <= VRAM_WIDTH && bottom <= PSX_VRAM_HEIGHT
}

#[derive(Clone, Debug)]
pub struct Dma {
    channels: [DmaChannel; DMA_CHANNEL_COUNT],
    pub control: u32,
    pub interrupt: u32,
    padding: [u32; 2],
}

impl Default for Dma {
    fn default() -> Self {
        Self {
            channels: [DmaChannel::default(); DMA_CHANNEL_COUNT],
            control: 0x0765_4321,
            interrupt: 0,
            padding: [0; 2],
        }
    }
}

impl Dma {
    pub fn channel_state(&self, channel: usize) -> Option<DmaChannelState> {
        self.channels.get(channel).map(|channel| DmaChannelState {
            madr: channel.madr,
            bcr: channel.bcr,
            chcr: channel.chcr,
        })
    }

    pub fn read_u32(&self, address: u32) -> u32 {
        match dma_register_slot(address) {
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Madr) => {
                self.channels[channel].madr
            }
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Bcr) => {
                self.channels[channel].bcr
            }
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Chcr) => {
                self.channels[channel].chcr
            }
            DmaRegisterSlot::Control => self.control,
            DmaRegisterSlot::Interrupt => self.interrupt_with_master_flag(),
            DmaRegisterSlot::Padding(index) => self.padding[index],
        }
    }

    pub fn write_u32(&mut self, address: u32, value: u32) {
        match dma_register_slot(address) {
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Madr) => {
                self.channels[channel].madr = value & 0x00ff_fffc;
            }
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Bcr) => {
                self.channels[channel].bcr = value;
            }
            DmaRegisterSlot::Channel(channel, DmaChannelRegister::Chcr) => {
                self.channels[channel].chcr = value;
                if value & (1 << 24) != 0 && !bus_driven_dma_channel(channel) {
                    self.complete_channel(channel);
                }
            }
            DmaRegisterSlot::Control => self.control = value,
            DmaRegisterSlot::Interrupt => self.write_interrupt(value),
            DmaRegisterSlot::Padding(index) => self.padding[index] = value,
        }
    }

    pub fn irq_pending(&self) -> bool {
        self.interrupt_with_master_flag() & (1 << 31) != 0
    }

    pub fn acknowledge_pending_irq_flags(&mut self) {
        let pending_flags = self.interrupt & DMA_INTERRUPT_FLAG_MASK;
        if pending_flags == 0 {
            return;
        }

        let preserved_control = self.interrupt & (DMA_INTERRUPT_IRQ_ENABLE_MASK | (1 << 23));
        self.write_interrupt(pending_flags | preserved_control);
    }

    pub fn complete_channel(&mut self, channel: usize) {
        if channel >= self.channels.len() {
            return;
        }

        self.channels[channel].chcr &= !(1 << 24);
        self.mark_channel_complete(channel);
    }

    fn mark_channel_complete(&mut self, channel: usize) {
        let channel_bit = 1 << (16 + channel);
        if self.interrupt & channel_bit != 0 {
            self.interrupt |= 1 << (24 + channel);
        }
    }

    fn write_interrupt(&mut self, value: u32) {
        let acknowledged = value & DMA_INTERRUPT_FLAG_MASK;
        let writable_mask = DMA_INTERRUPT_IRQ_ENABLE_MASK | (1 << 23);
        let writable = value & writable_mask;
        self.interrupt = (self.interrupt & !acknowledged & !writable_mask) | writable;
    }

    fn write_interrupt_lane(&mut self, address: u32, value: u32, access_len: usize) {
        let shift = (address - DMA_INTERRUPT) * 8;
        let lane_mask = match access_len {
            1 => 0xff,
            2 => 0xffff,
            _ => u32::MAX,
        } << shift;
        let lane_value = (value << shift) & lane_mask;
        let writable_mask = lane_mask & (DMA_INTERRUPT_IRQ_ENABLE_MASK | (1 << 23));
        let acknowledged = lane_value & DMA_INTERRUPT_FLAG_MASK;
        self.interrupt =
            (self.interrupt & !acknowledged & !writable_mask) | (lane_value & writable_mask);
    }

    fn interrupt_with_master_flag(&self) -> u32 {
        let master_enabled = self.interrupt & (1 << 23) != 0;
        let enabled_flags = ((self.interrupt & DMA_INTERRUPT_FLAG_MASK) >> 8)
            & self.interrupt
            & DMA_INTERRUPT_IRQ_ENABLE_MASK;
        if master_enabled && enabled_flags != 0 {
            self.interrupt | (1 << 31)
        } else {
            self.interrupt & !(1 << 31)
        }
    }
}

fn bus_driven_dma_channel(channel: usize) -> bool {
    matches!(channel, 0 | 1 | 2 | 6)
}

#[derive(Clone, Copy, Debug, Default)]
struct DmaChannel {
    madr: u32,
    bcr: u32,
    chcr: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DmaChannelState {
    pub madr: u32,
    pub bcr: u32,
    pub chcr: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DmaChannelRegister {
    Madr,
    Bcr,
    Chcr,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DmaRegisterSlot {
    Channel(usize, DmaChannelRegister),
    Control,
    Interrupt,
    Padding(usize),
}

fn dma_register_slot(address: u32) -> DmaRegisterSlot {
    match address {
        DMA_CONTROL => DmaRegisterSlot::Control,
        DMA_INTERRUPT => DmaRegisterSlot::Interrupt,
        0x1f80_10f8 => DmaRegisterSlot::Padding(0),
        0x1f80_10fc => DmaRegisterSlot::Padding(1),
        _ => {
            let channel = ((address - DMA_REGION_START) / DMA_CHANNEL_STRIDE) as usize;
            let register = match (address - DMA_REGION_START) % DMA_CHANNEL_STRIDE {
                0x0 => DmaChannelRegister::Madr,
                0x4 => DmaChannelRegister::Bcr,
                _ => DmaChannelRegister::Chcr,
            };
            DmaRegisterSlot::Channel(channel.min(DMA_CHANNEL_COUNT - 1), register)
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Timers(pub [Timer; 3]);

impl Timers {
    pub fn tick(&mut self, cycles: u64) -> u32 {
        let mut irq_status = 0;
        for (index, timer) in self.0.iter_mut().enumerate() {
            if timer.tick(cycles) {
                irq_status |= 1 << (4 + index);
            }
        }
        irq_status
    }

    fn read_u32(&self, address: u32) -> u32 {
        let (timer, register) = timer_register_slot(address);
        self.0[timer].read(register) as u32
    }

    fn write_u32(&mut self, address: u32, value: u32) {
        let (timer, register) = timer_register_slot(address);
        self.0[timer].write(register, value as u16);
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Timer {
    pub counter: u16,
    pub mode: u16,
    pub target: u16,
    cycle_accumulator: u64,
    irq_fired: bool,
}

impl Timer {
    fn tick(&mut self, cycles: u64) -> bool {
        const TIMER_COUNTER_DIVISOR: u64 = 128;
        const MODE_RESET_AT_TARGET: u16 = 1 << 3;
        const MODE_IRQ_AT_TARGET: u16 = 1 << 4;
        const MODE_IRQ_AT_OVERFLOW: u16 = 1 << 5;
        const MODE_IRQ_REPEAT: u16 = 1 << 6;
        const MODE_IRQ_TOGGLE: u16 = 1 << 7;
        const MODE_IRQ_NOT_REQUESTED: u16 = 1 << 10;
        const MODE_REACHED_TARGET: u16 = 1 << 11;
        const MODE_REACHED_OVERFLOW: u16 = 1 << 12;

        self.cycle_accumulator = self.cycle_accumulator.saturating_add(cycles);
        let increments = self.cycle_accumulator / TIMER_COUNTER_DIVISOR;
        self.cycle_accumulator %= TIMER_COUNTER_DIVISOR;
        if increments == 0 {
            return false;
        }

        let start = u64::from(self.counter);
        let target = u64::from(self.target);
        let reset_at_target = self.mode & MODE_RESET_AT_TARGET != 0 && target > 0;
        let reached_target = target > 0 && start.saturating_add(increments) >= target;
        let reached_overflow = start.saturating_add(increments) > u64::from(u16::MAX);

        self.counter = if reset_at_target {
            let period = target.saturating_add(1);
            ((start.saturating_add(increments)) % period) as u16
        } else {
            self.counter.wrapping_add(increments as u16)
        };

        if reached_target {
            self.mode |= MODE_REACHED_TARGET;
        }
        if reached_overflow {
            self.mode |= MODE_REACHED_OVERFLOW;
        }

        let irq_requested = (reached_target && self.mode & MODE_IRQ_AT_TARGET != 0)
            || (reached_overflow && self.mode & MODE_IRQ_AT_OVERFLOW != 0);
        let repeat_irq = self.mode & MODE_IRQ_REPEAT != 0;
        if !irq_requested || (self.irq_fired && !repeat_irq) {
            return false;
        }

        self.irq_fired = true;
        if self.mode & MODE_IRQ_TOGGLE != 0 {
            self.mode ^= MODE_IRQ_NOT_REQUESTED;
        } else {
            self.mode &= !MODE_IRQ_NOT_REQUESTED;
        }
        true
    }

    fn read(self, register: TimerRegister) -> u16 {
        match register {
            TimerRegister::Counter => self.counter,
            TimerRegister::Mode => self.mode,
            TimerRegister::Target => self.target,
        }
    }

    fn write(&mut self, register: TimerRegister, value: u16) {
        match register {
            TimerRegister::Counter => {
                self.counter = value;
                self.cycle_accumulator = 0;
            }
            TimerRegister::Mode => {
                self.mode = (value & 0x03ff) | (1 << 10);
                self.irq_fired = false;
            }
            TimerRegister::Target => self.target = value,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TimerRegister {
    Counter,
    Mode,
    Target,
}

fn timer_register_slot(address: u32) -> (usize, TimerRegister) {
    let timer = ((address - TIMER0_COUNTER) / 0x10) as usize;
    let register = match (address - TIMER0_COUNTER) % 0x10 {
        0x0 => TimerRegister::Counter,
        0x4 => TimerRegister::Mode,
        _ => TimerRegister::Target,
    };
    (timer.min(2), register)
}

#[derive(Clone, Debug)]
pub struct Controller {
    pub p1_state: u16,
    pub last_write: u16,
    pub status: u16,
    pub mode: u16,
    pub control: u16,
    pub baud: u16,
    transfer_index: u8,
    security_transfer_index: usize,
    security_response: Vec<u8>,
    cat702: [Option<Cat702>; 2],
    zn_mcu: ZnMcu,
    input_activity: ControllerInputActivity,
    response: u8,
    irq_requested: bool,
    recent_security_transfers: Vec<SecurityTransferTraceEntry>,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct ControllerInputActivity {
    pub p1_input_reads: u64,
    pub p1_up_active_reads: u64,
    pub p1_down_active_reads: u64,
    pub p1_left_active_reads: u64,
    pub p1_right_active_reads: u64,
    pub p1_start_active_reads: u64,
    pub p1_punch_active_reads: u64,
    pub p1_kick_active_reads: u64,
    pub p1_beast_active_reads: u64,
    pub p1_guard_active_reads: u64,
}

impl ControllerInputActivity {
    fn json(self) -> String {
        format!(
            "{{\"p1_input_reads\":{},\"p1_up_active_reads\":{},\"p1_down_active_reads\":{},\"p1_left_active_reads\":{},\"p1_right_active_reads\":{},\"p1_start_active_reads\":{},\"p1_punch_active_reads\":{},\"p1_kick_active_reads\":{},\"p1_beast_active_reads\":{},\"p1_guard_active_reads\":{}}}",
            self.p1_input_reads,
            self.p1_up_active_reads,
            self.p1_down_active_reads,
            self.p1_left_active_reads,
            self.p1_right_active_reads,
            self.p1_start_active_reads,
            self.p1_punch_active_reads,
            self.p1_kick_active_reads,
            self.p1_beast_active_reads,
            self.p1_guard_active_reads
        )
    }
}

impl Default for Controller {
    fn default() -> Self {
        Self {
            p1_state: 0xffff,
            last_write: 0,
            status: 0x0005,
            mode: 0,
            control: 0,
            baud: 0,
            transfer_index: 0,
            security_transfer_index: 0,
            security_response: Vec::new(),
            cat702: [None, None],
            zn_mcu: ZnMcu::default(),
            input_activity: ControllerInputActivity::default(),
            response: 0xff,
            irq_requested: false,
            recent_security_transfers: Vec::new(),
        }
    }
}

impl Controller {
    pub fn set_security_response(&mut self, response: Vec<u8>) {
        self.security_response = response;
        self.security_transfer_index = 0;
        self.response = 0xff;
        self.status |= 0x0003;
    }

    pub fn set_cat702_transforms(&mut self, cat702_1: Option<[u8; 8]>, cat702_2: Option<[u8; 8]>) {
        self.cat702 = [cat702_1.map(Cat702::new), cat702_2.map(Cat702::new)];
        self.response = 0xff;
        self.status |= 0x0003;
    }

    pub fn set_security_selects(
        &mut self,
        cat702_1_select: bool,
        cat702_2_select: bool,
        zn_mcu_analog_read: bool,
        zn_mcu_trackball_read: bool,
        zn_mcu_selected: bool,
    ) {
        if let Some(cat702) = &mut self.cat702[0] {
            cat702.write_select(cat702_1_select);
        }
        if let Some(cat702) = &mut self.cat702[1] {
            cat702.write_select(cat702_2_select);
        }
        self.zn_mcu
            .set_lines(zn_mcu_analog_read, zn_mcu_trackball_read, zn_mcu_selected);
    }

    pub fn zn_mcu_diagnostic_json(&self) -> String {
        self.zn_mcu.diagnostic_json()
    }

    pub fn diagnostic_json(&self) -> String {
        format!(
            "{{\"p1_state\":{},\"p1_state_hex\":\"0x{:04x}\",\"last_write\":{},\"last_write_hex\":\"0x{:04x}\",\"status\":{},\"status_hex\":\"0x{:04x}\",\"mode\":{},\"mode_hex\":\"0x{:04x}\",\"control\":{},\"control_hex\":\"0x{:04x}\",\"baud\":{},\"baud_hex\":\"0x{:04x}\",\"transfer_index\":{},\"security_transfer_index\":{},\"security_response_loaded\":{},\"security_response_len\":{},\"response\":{},\"response_hex\":\"0x{:02x}\",\"irq_requested\":{},\"cat702\":[{}],\"zn_mcu\":{},\"input_activity\":{},\"recent_security_transfers\":[{}]}}",
            self.p1_state,
            self.p1_state,
            self.last_write,
            self.last_write,
            self.status,
            self.status,
            self.mode,
            self.mode,
            self.control,
            self.control,
            self.baud,
            self.baud,
            self.transfer_index,
            self.security_transfer_index,
            !self.security_response.is_empty(),
            self.security_response.len(),
            self.response,
            self.response,
            self.irq_requested,
            self.cat702_diagnostic_json(),
            self.zn_mcu.diagnostic_json(),
            self.input_activity.json(),
            self.recent_security_transfers_json()
        )
    }

    pub fn security_compact_json(&self) -> String {
        format!(
            "{{\"last_write\":{},\"last_write_hex\":\"0x{:04x}\",\"status\":{},\"status_hex\":\"0x{:04x}\",\"control\":{},\"control_hex\":\"0x{:04x}\",\"transfer_index\":{},\"security_transfer_index\":{},\"security_response_loaded\":{},\"security_response_len\":{},\"response\":{},\"response_hex\":\"0x{:02x}\",\"irq_requested\":{},\"cat702\":[{}],\"zn_mcu\":{},\"input_activity\":{}}}",
            self.last_write,
            self.last_write,
            self.status,
            self.status,
            self.control,
            self.control,
            self.transfer_index,
            self.security_transfer_index,
            !self.security_response.is_empty(),
            self.security_response.len(),
            self.response,
            self.response,
            self.irq_requested,
            self.cat702_diagnostic_json(),
            self.zn_mcu.diagnostic_json(),
            self.input_activity.json()
        )
    }

    pub fn input_activity(&self) -> ControllerInputActivity {
        self.input_activity
    }

    fn cat702_diagnostic_json(&self) -> String {
        self.cat702
            .iter()
            .enumerate()
            .map(|(index, cat702)| match cat702 {
                Some(cat702) => cat702.diagnostic_json(index),
                None => format!("{{\"index\":{},\"loaded\":false}}", index),
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn recent_security_transfers_json(&self) -> String {
        self.recent_security_transfers
            .iter()
            .map(SecurityTransferTraceEntry::json)
            .collect::<Vec<_>>()
            .join(",")
    }

    fn irq_requested(&self) -> bool {
        self.irq_requested
    }

    fn read_u32(&self, address: u32) -> u32 {
        match address {
            SIO_DATA => self.response as u32,
            SIO_STATUS => self.status as u32,
            SIO_MODE => self.mode as u32,
            SIO_CONTROL => self.control as u32,
            SIO_BAUD => self.baud as u32,
            _ => 0,
        }
    }

    fn write_u32(&mut self, address: u32, value: u32) {
        match address {
            SIO_DATA => self.write_data(value as u16),
            SIO_MODE => self.mode = value as u16,
            SIO_CONTROL => self.write_control(value as u16),
            SIO_BAUD => self.baud = value as u16,
            _ => {}
        }
    }

    fn write_data(&mut self, value: u16) {
        self.last_write = value;
        let value = value as u8;
        if self.cat702_selected() {
            let cat702_response = self.transfer_cat702_byte(value);
            self.response = if self.zn_mcu.is_selected() {
                cat702_response & self.zn_mcu.shared_bus_dataout_byte(value)
            } else {
                cat702_response
            };
            let device = if self.zn_mcu.is_selected() {
                "cat702+zn_mcu_passive"
            } else {
                "cat702"
            };
            self.record_security_transfer(device, value, self.response);
        } else if self.zn_mcu.is_selected() {
            self.response = self.zn_mcu.transfer_byte();
            self.record_security_transfer("zn_mcu", value, self.response);
        } else if self.security_response.is_empty() || value == 0x01 {
            let transfer_index = self.transfer_index;
            self.response = match transfer_index {
                0 => 0xff,
                1 if value == 0x42 => 0x41,
                1 => 0xff,
                2 => 0x5a,
                3 => self.p1_state as u8,
                4 => (self.p1_state >> 8) as u8,
                _ => 0xff,
            };
            if transfer_index == 3 {
                self.record_p1_input_read();
            }
            self.transfer_index = if value == 0x01 {
                1
            } else {
                self.transfer_index.saturating_add(1)
            };
            self.record_security_transfer("controller", value, self.response);
        } else {
            self.response = self.security_response_byte();
            self.security_transfer_index = self.security_transfer_index.saturating_add(1);
            self.record_security_transfer("bios_security", value, self.response);
        }
        self.irq_requested = true;
        self.status |= 0x0003 | SIO_STATUS_IRQ_REQUEST;
    }

    fn record_security_transfer(&mut self, device: &'static str, request: u8, response: u8) {
        if self.recent_security_transfers.len() >= SIO_SECURITY_TRANSFER_TRACE_LIMIT {
            self.recent_security_transfers.remove(0);
        }

        self.recent_security_transfers
            .push(SecurityTransferTraceEntry {
                device,
                request,
                response,
                cat702_1_selected: self
                    .cat702
                    .first()
                    .and_then(Option::as_ref)
                    .is_some_and(Cat702::is_selected),
                cat702_2_selected: self
                    .cat702
                    .get(1)
                    .and_then(Option::as_ref)
                    .is_some_and(Cat702::is_selected),
                zn_mcu_selected: self.zn_mcu.is_selected(),
                zn_mcu_analog_read: self.zn_mcu.analog_read,
                zn_mcu_trackball_read: self.zn_mcu.trackball_read,
            });
    }

    fn write_control(&mut self, value: u16) {
        self.control = value;
        if value & 0x0040 != 0 {
            self.transfer_index = 0;
            self.security_transfer_index = 0;
            self.zn_mcu.reset_transfer();
            self.response = 0xff;
            self.irq_requested = false;
            self.status = 0x0007;
        } else if value & 0x0010 != 0 {
            self.irq_requested = false;
            self.status &= !SIO_STATUS_IRQ_REQUEST;
        } else if value & 0x0003 == 0x0003 {
            self.security_transfer_index = 0;
            self.zn_mcu.reset_transfer();
            self.status |= 0x0003;
        }
    }

    fn security_response_byte(&self) -> u8 {
        if self.security_transfer_index == 0 {
            return 0xff;
        }

        self.security_response
            .get(self.security_transfer_index - 1)
            .copied()
            .unwrap_or(0xff)
    }

    fn cat702_selected(&self) -> bool {
        self.cat702
            .iter()
            .flatten()
            .any(|cat702| cat702.is_selected())
    }

    fn transfer_cat702_byte(&mut self, value: u8) -> u8 {
        let mut response = 0u8;
        for bit in 0..8 {
            let datain = (value >> bit) & 1 != 0;
            let mut dataout = true;
            for cat702 in self.cat702.iter_mut().flatten() {
                dataout &= cat702.transfer_bit(datain);
            }
            if dataout {
                response |= 1 << bit;
            }
        }
        response
    }

    pub fn set_buttons(&mut self, buttons: ActionButtons) {
        let mut state = 0xffff_u16;
        clear_if(&mut state, 0x0010, buttons.up);
        clear_if(&mut state, 0x0040, buttons.down);
        clear_if(&mut state, 0x0080, buttons.left);
        clear_if(&mut state, 0x0020, buttons.right);
        clear_if(&mut state, 0x4000, buttons.punch);
        clear_if(&mut state, 0x2000, buttons.kick);
        clear_if(&mut state, 0x1000, buttons.beast);
        clear_if(&mut state, 0x8000, buttons.guard);
        clear_if(&mut state, 0x0008, buttons.start);
        self.p1_state = state;
        self.zn_mcu.set_input(buttons);
    }

    fn record_p1_input_read(&mut self) {
        self.input_activity.p1_input_reads = self.input_activity.p1_input_reads.saturating_add(1);
        increment_if_u64(
            &mut self.input_activity.p1_up_active_reads,
            self.p1_state & 0x0010 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_down_active_reads,
            self.p1_state & 0x0040 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_left_active_reads,
            self.p1_state & 0x0080 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_right_active_reads,
            self.p1_state & 0x0020 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_start_active_reads,
            self.p1_state & 0x0008 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_punch_active_reads,
            self.p1_state & 0x4000 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_kick_active_reads,
            self.p1_state & 0x2000 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_beast_active_reads,
            self.p1_state & 0x1000 == 0,
        );
        increment_if_u64(
            &mut self.input_activity.p1_guard_active_reads,
            self.p1_state & 0x8000 == 0,
        );
    }
}

#[derive(Clone, Debug)]
struct SecurityTransferTraceEntry {
    device: &'static str,
    request: u8,
    response: u8,
    cat702_1_selected: bool,
    cat702_2_selected: bool,
    zn_mcu_selected: bool,
    zn_mcu_analog_read: bool,
    zn_mcu_trackball_read: bool,
}

impl SecurityTransferTraceEntry {
    fn json(&self) -> String {
        format!(
            "{{\"device\":\"{}\",\"request\":{},\"request_hex\":\"0x{:02x}\",\"response\":{},\"response_hex\":\"0x{:02x}\",\"cat702_1_selected\":{},\"cat702_2_selected\":{},\"zn_mcu_selected\":{},\"zn_mcu_analog_read\":{},\"zn_mcu_trackball_read\":{}}}",
            self.device,
            self.request,
            self.request,
            self.response,
            self.response,
            self.cat702_1_selected,
            self.cat702_2_selected,
            self.zn_mcu_selected,
            self.zn_mcu_analog_read,
            self.zn_mcu_trackball_read
        )
    }
}

fn increment_if_u64(counter: &mut u64, condition: bool) {
    if condition {
        *counter = counter.saturating_add(1);
    }
}

#[derive(Clone, Debug)]
struct ZnMcu {
    analog_read: bool,
    trackball_read: bool,
    selected: bool,
    dsw: u8,
    input: ActionButtons,
    send: [u8; 9],
    databytes: usize,
    byte_index: usize,
    bit_index: u8,
    dsr: bool,
    txd: bool,
    select_transitions: u64,
    transferred_bytes: u64,
    transferred_bits: u64,
    last_response: u8,
}

impl Default for ZnMcu {
    fn default() -> Self {
        Self {
            analog_read: false,
            trackball_read: false,
            selected: false,
            dsw: 0x0f,
            input: ActionButtons::default(),
            send: [0; 9],
            databytes: 0,
            byte_index: 0,
            bit_index: 0,
            dsr: true,
            txd: true,
            select_transitions: 0,
            transferred_bytes: 0,
            transferred_bits: 0,
            last_response: 0xff,
        }
    }
}

impl ZnMcu {
    fn set_lines(&mut self, analog_read: bool, trackball_read: bool, selected: bool) {
        let mode_changed = self.analog_read != analog_read || self.trackball_read != trackball_read;
        let became_selected = selected && !self.selected;

        self.analog_read = analog_read;
        self.trackball_read = trackball_read;

        if became_selected {
            self.select_transitions = self.select_transitions.saturating_add(1);
        }

        if became_selected || (selected && mode_changed) {
            self.begin_transfer();
        } else if !selected && self.selected {
            self.end_transfer();
        }

        self.selected = selected;
    }

    fn is_selected(&self) -> bool {
        self.selected
    }

    fn reset_transfer(&mut self) {
        self.byte_index = 0;
        self.bit_index = 0;
        self.txd = true;
        if self.selected {
            self.rebuild_send_buffer();
        }
    }

    fn set_input(&mut self, input: ActionButtons) {
        if self.input == input {
            return;
        }

        self.input = input;
        if self.selected {
            self.rebuild_send_buffer();
            if self.byte_index > self.databytes {
                self.byte_index = 0;
                self.bit_index = 0;
            }
        }
    }

    fn transfer_byte(&mut self) -> u8 {
        if !self.selected {
            self.last_response = 0xff;
            return 0xff;
        }
        if self.byte_index == 0 && self.bit_index == 0 {
            self.rebuild_send_buffer();
        }

        let mut response = 0u8;
        for bit in 0..8 {
            if self.clock_falling_edge_dataout() {
                response |= 1 << bit;
            }
        }
        self.transferred_bytes = self.transferred_bytes.saturating_add(1);
        self.last_response = response;
        response
    }

    fn shared_bus_dataout_byte(&mut self, _request: u8) -> u8 {
        // The ZN MCU is physically connected to the shared SIO RXD line, but
        // CAT702 security exchanges send BIOS/license bytes rather than the
        // MCU controller-poll protocol. Until the MCU is modeled at clock-edge
        // level, keep its shared-line output passive-high so CAT702 traffic is
        // not corrupted by the simplified packet helper.
        self.last_response = 0xff;
        0xff
    }

    fn begin_transfer(&mut self) {
        self.byte_index = 0;
        self.bit_index = 0;
        self.dsr = false;
        self.txd = true;
        self.rebuild_send_buffer();
        self.dsr = true;
    }

    fn end_transfer(&mut self) {
        self.byte_index = 0;
        self.bit_index = 0;
        self.databytes = 0;
        self.send = [0; 9];
        self.dsr = true;
        self.txd = true;
    }

    fn clock_falling_edge_dataout(&mut self) -> bool {
        let data = if self.byte_index <= self.databytes && self.byte_index < self.send.len() {
            self.send[self.byte_index]
        } else {
            0
        };
        self.txd = data & (1 << self.bit_index) != 0;
        self.transferred_bits = self.transferred_bits.saturating_add(1);

        self.bit_index = self.bit_index.saturating_add(1);
        if self.bit_index == 8 {
            self.bit_index = 0;
            self.byte_index = self.byte_index.saturating_add(1);
            if self.byte_index <= self.databytes {
                self.dsr = true;
            }
        }

        self.txd
    }

    fn rebuild_send_buffer(&mut self) {
        self.databytes = if self.analog_read {
            8
        } else if self.trackball_read {
            6
        } else {
            1
        };

        self.send = [0; 9];
        self.send[0] = ((self.databytes as u8) << 4) | (self.dsw & 0x0f);

        if self.analog_read {
            self.send[1..=8].fill(0xff);
        } else if self.trackball_read {
            self.send[1..=6].fill(0x00);
        } else {
            self.send[1] = zn_mcu_digital_input_payload(self.input);
        }
    }

    fn diagnostic_json(&self) -> String {
        format!(
            "{{\"selected\":{},\"analog_read\":{},\"trackball_read\":{},\"dsw\":{},\"dsw_hex\":\"0x{:02x}\",\"databytes\":{},\"byte_index\":{},\"bit_index\":{},\"dsr\":{},\"txd\":{},\"select_transitions\":{},\"transferred_bits\":{},\"transferred_bytes\":{},\"last_response\":{},\"last_response_hex\":\"0x{:02x}\"}}",
            self.selected,
            self.analog_read,
            self.trackball_read,
            self.dsw,
            self.dsw,
            self.databytes,
            self.byte_index,
            self.bit_index,
            self.dsr,
            self.txd,
            self.select_transitions,
            self.transferred_bits,
            self.transferred_bytes,
            self.last_response,
            self.last_response
        )
    }
}

fn zn_mcu_digital_input_payload(input: ActionButtons) -> u8 {
    let mut value = 0xff;
    clear_bit_if_u8(&mut value, 0x01, input.up);
    clear_bit_if_u8(&mut value, 0x02, input.down);
    clear_bit_if_u8(&mut value, 0x04, input.left);
    clear_bit_if_u8(&mut value, 0x08, input.right);
    clear_bit_if_u8(&mut value, 0x10, input.punch);
    clear_bit_if_u8(&mut value, 0x20, input.kick);
    clear_bit_if_u8(&mut value, 0x40, input.beast);
    clear_bit_if_u8(&mut value, 0x80, input.start);
    value
}

fn clear_bit_if_u8(value: &mut u8, bit: u8, active: bool) {
    if active {
        *value &= !bit;
    }
}

#[derive(Clone, Debug)]
struct Cat702 {
    transform: [u8; 8],
    select: bool,
    state: u8,
    bit: u8,
    dataout: bool,
    select_transitions: u64,
    transferred_bits: u64,
    last_datain: bool,
}

impl Cat702 {
    const INITIAL_SBOX: [u8; 8] = [0xff, 0xfe, 0xfc, 0xf8, 0xf0, 0xe0, 0xc0, 0x7f];

    fn new(transform: [u8; 8]) -> Self {
        Self {
            transform,
            select: true,
            state: 0,
            bit: 0,
            dataout: true,
            select_transitions: 0,
            transferred_bits: 0,
            last_datain: true,
        }
    }

    fn write_select(&mut self, select: bool) {
        if self.select == select {
            return;
        }

        self.select_transitions = self.select_transitions.saturating_add(1);
        if select {
            self.dataout = true;
        } else {
            self.state = 0xfc;
            self.bit = 0;
        }
        self.select = select;
    }

    fn is_selected(&self) -> bool {
        !self.select
    }

    fn diagnostic_json(&self, index: usize) -> String {
        format!(
            "{{\"index\":{},\"loaded\":true,\"select_line\":{},\"selected\":{},\"state\":{},\"state_hex\":\"0x{:02x}\",\"bit\":{},\"dataout\":{},\"select_transitions\":{},\"transferred_bits\":{},\"transferred_bytes\":{},\"last_datain\":{}}}",
            index,
            self.select,
            self.is_selected(),
            self.state,
            self.state,
            self.bit,
            self.dataout,
            self.select_transitions,
            self.transferred_bits,
            self.transferred_bits / 8,
            self.last_datain
        )
    }

    fn transfer_bit(&mut self, datain: bool) -> bool {
        if self.select {
            self.dataout = true;
            return true;
        }

        self.transferred_bits = self.transferred_bits.saturating_add(1);
        self.last_datain = datain;
        if self.bit == 0 {
            self.apply_sbox(&Self::INITIAL_SBOX);
        }

        self.dataout = self.state & (1 << self.bit) != 0;
        if !datain {
            self.apply_bit_sbox(self.bit);
        }
        self.bit = self.bit.wrapping_add(1) & 7;
        self.dataout
    }

    fn apply_sbox(&mut self, sbox: &[u8; 8]) {
        let mut next = 0u8;
        for (bit, coefficient) in sbox.iter().enumerate() {
            if self.state & (1 << bit) != 0 {
                next ^= *coefficient;
            }
        }
        self.state = next;
    }

    fn apply_bit_sbox(&mut self, selector: u8) {
        let mut next = 0u8;
        for bit in 0..8 {
            if self.state & (1 << bit) != 0 {
                next ^= self.sbox_coefficient(selector, bit as u8);
            }
        }
        self.state = next;
    }

    fn sbox_coefficient(&self, selector: u8, bit: u8) -> u8 {
        if selector == 0 {
            return self.transform[bit as usize];
        }

        let previous = self.sbox_coefficient(selector.wrapping_sub(1) & 7, bit.wrapping_sub(1) & 7);
        let shifted = (previous << 1) | (((previous >> 7) ^ (previous >> 6)) & 1);
        if bit == 7 {
            shifted ^ self.sbox_coefficient(selector, 0)
        } else {
            shifted
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Cdrom {
    index: u8,
    status: u8,
    response: u8,
    data: u8,
    interrupt_enable: u8,
    last_command: u8,
}

impl Cdrom {
    fn read_u32(&self, address: u32) -> u32 {
        match address {
            CDROM_INDEX_STATUS => ((self.status | 0x18) & !0x03) as u32 | self.index as u32,
            CDROM_RESPONSE => self.response as u32,
            CDROM_DATA => self.data as u32,
            CDROM_INTERRUPT_ENABLE => self.interrupt_enable as u32,
            _ => 0,
        }
    }

    fn write_u32(&mut self, address: u32, value: u32) {
        let value = value as u8;
        match address {
            CDROM_INDEX_STATUS => self.index = value & 0x03,
            CDROM_RESPONSE => {
                self.last_command = value;
                self.response = 0x00;
            }
            CDROM_DATA => self.data = value,
            CDROM_INTERRUPT_ENABLE => self.interrupt_enable = value,
            _ => {}
        }
    }
}

#[derive(Clone, Debug)]
pub struct Mdec {
    command: u32,
    control: u32,
    status: u32,
    input_words_remaining: u32,
    dma_input_words: u64,
    dma_output_words: u64,
    input_words: Vec<u32>,
    decoded_output_words: Vec<u32>,
    decoded_output_index: usize,
    decoded_output_underflow_reads: u64,
    last_decoded_output_words: usize,
    quant_luma: [u8; 64],
    quant_chroma: [u8; 64],
    scale_table: [i16; 64],
}

impl Default for Mdec {
    fn default() -> Self {
        Self {
            command: 0,
            control: 0,
            status: mdec_ready_status(),
            input_words_remaining: 0,
            dma_input_words: 0,
            dma_output_words: 0,
            input_words: Vec::new(),
            decoded_output_words: Vec::new(),
            decoded_output_index: 0,
            decoded_output_underflow_reads: 0,
            last_decoded_output_words: 0,
            quant_luma: [8; 64],
            quant_chroma: [8; 64],
            scale_table: [0; 64],
        }
    }
}

impl Mdec {
    fn read_u32(&self, address: u32) -> u32 {
        match address {
            MDEC_COMMAND => self.command,
            MDEC_STATUS => self.status,
            _ => 0,
        }
    }

    fn write_u32(&mut self, address: u32, value: u32) {
        match address {
            MDEC_COMMAND => self.write_command_or_data(value),
            MDEC_STATUS => {
                if value & 0x8000_0000 != 0 {
                    *self = Self::default();
                } else {
                    self.control = value & 0x6000_0000;
                    self.status = mdec_status(self.input_words_remaining);
                }
            }
            _ => {}
        }
    }

    pub fn write_dma_input(&mut self, value: u32) {
        self.dma_input_words = self.dma_input_words.saturating_add(1);
        self.write_command_or_data(value);
    }

    fn write_command_or_data(&mut self, value: u32) {
        if self.input_words_remaining == 0 {
            self.start_command(value);
        } else {
            self.input_words.push(value);
            self.input_words_remaining = self.input_words_remaining.saturating_sub(1);
            if self.input_words_remaining == 0 {
                self.finish_input_dma();
            }
        }
        self.status = mdec_status(self.input_words_remaining);
    }

    fn start_command(&mut self, value: u32) {
        self.command = value;
        self.input_words_remaining = mdec_input_words_for_command(value);
        self.input_words.clear();
        self.decoded_output_words.clear();
        self.decoded_output_index = 0;
        self.last_decoded_output_words = 0;
        if self.input_words_remaining == 0 {
            self.finish_input_dma();
        }
    }

    pub fn read_dma_output(&mut self) -> u32 {
        self.dma_output_words = self.dma_output_words.saturating_add(1);
        self.status = mdec_status(self.input_words_remaining);
        if self.decoded_output_index >= self.decoded_output_words.len() {
            self.decoded_output_underflow_reads =
                self.decoded_output_underflow_reads.saturating_add(1);
            return 0;
        }
        let word = self.decoded_output_words[self.decoded_output_index];
        self.decoded_output_index = self.decoded_output_index.saturating_add(1);
        word
    }

    pub fn read_disabled_dma_output(&mut self) -> u32 {
        self.dma_output_words = self.dma_output_words.saturating_add(1);
        self.status = mdec_status(self.input_words_remaining);
        if self.decoded_output_index < self.decoded_output_words.len() {
            self.decoded_output_index = self.decoded_output_index.saturating_add(1);
        } else {
            self.decoded_output_underflow_reads =
                self.decoded_output_underflow_reads.saturating_add(1);
        }
        0
    }

    fn finish_input_dma(&mut self) {
        self.decoded_output_words.clear();
        self.decoded_output_index = 0;
        match self.command >> 29 {
            0x1 => {
                self.decoded_output_words = decode_mdec_macroblocks(
                    &self.input_words,
                    &self.quant_luma,
                    &self.quant_chroma,
                    &self.scale_table,
                    self.command,
                );
            }
            0x2 => self.set_quant_tables(),
            0x3 => self.set_scale_table(),
            _ => {}
        }
        self.last_decoded_output_words = self.decoded_output_words.len();
    }

    fn set_quant_tables(&mut self) {
        let bytes = mdec_bytes(&self.input_words);
        for (index, value) in bytes.iter().take(64).copied().enumerate() {
            self.quant_luma[index] = value.max(1);
        }
        if bytes.len() >= 128 {
            for (index, value) in bytes.iter().skip(64).take(64).copied().enumerate() {
                self.quant_chroma[index] = value.max(1);
            }
        } else {
            self.quant_chroma = self.quant_luma;
        }
    }

    fn set_scale_table(&mut self) {
        let values = mdec_halfwords(&self.input_words);
        for y in 0..8 {
            for x in 0..8 {
                self.scale_table[y * 8 + x] = values.get(x * 8 + y).copied().unwrap_or(0) as i16;
            }
        }
    }

    pub fn input_words_remaining(&self) -> u32 {
        self.input_words_remaining
    }

    pub fn dma_input_words(&self) -> u64 {
        self.dma_input_words
    }

    pub fn dma_output_words(&self) -> u64 {
        self.dma_output_words
    }

    pub fn command(&self) -> u32 {
        self.command
    }

    pub fn decoded_output_index(&self) -> usize {
        self.decoded_output_index
    }

    pub fn decoded_output_words(&self) -> usize {
        self.decoded_output_words.len()
    }

    pub fn diagnostic_json(&self) -> String {
        let consumed_output_words = self
            .decoded_output_index
            .min(self.decoded_output_words.len());
        let first_output_words = self
            .decoded_output_words
            .iter()
            .take(16)
            .map(|word| format!("\"0x{word:08x}\""))
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"command\":{},\"command_hex\":\"0x{:08x}\",\"control\":{},\"control_hex\":\"0x{:08x}\",\"status\":{},\"status_hex\":\"0x{:08x}\",\"input_words_remaining\":{},\"dma_input_words\":{},\"dma_output_words\":{},\"last_decoded_output_words\":{},\"decoded_output_index\":{},\"decoded_output_underflow_reads\":{},\"quant_luma_checksum\":{},\"quant_chroma_checksum\":{},\"scale_table_checksum\":{},\"scale_table_nonzero\":{},\"decoded_output_checksum\":{},\"consumed_output_words\":{},\"consumed_output_checksum\":{},\"first_output_words_hex\":[{}],\"rgb555_output_layout\":\"{}\"}}",
            self.command,
            self.command,
            self.control,
            self.control,
            self.status,
            self.status,
            self.input_words_remaining,
            self.dma_input_words,
            self.dma_output_words,
            self.last_decoded_output_words,
            self.decoded_output_index,
            self.decoded_output_underflow_reads,
            mdec_u8_checksum(&self.quant_luma),
            mdec_u8_checksum(&self.quant_chroma),
            mdec_i16_checksum(&self.scale_table),
            self.scale_table.iter().filter(|value| **value != 0).count(),
            mdec_u32_checksum(&self.decoded_output_words),
            consumed_output_words,
            mdec_u32_checksum(&self.decoded_output_words[..consumed_output_words]),
            first_output_words,
            native_mdec_rgb555_output_layout()
        )
    }
}

fn mdec_u8_checksum(values: &[u8]) -> u32 {
    values.iter().fold(0x811c_9dc5_u32, |hash, value| {
        (hash ^ u32::from(*value)).wrapping_mul(0x0100_0193)
    })
}

fn mdec_i16_checksum(values: &[i16]) -> u32 {
    values.iter().fold(0x811c_9dc5_u32, |hash, value| {
        value.to_le_bytes().into_iter().fold(hash, |hash, byte| {
            (hash ^ u32::from(byte)).wrapping_mul(0x0100_0193)
        })
    })
}

fn mdec_u32_checksum(values: &[u32]) -> u32 {
    values.iter().fold(0x811c_9dc5_u32, |hash, value| {
        value.to_le_bytes().into_iter().fold(hash, |hash, byte| {
            (hash ^ u32::from(byte)).wrapping_mul(0x0100_0193)
        })
    })
}

fn mdec_input_words_for_command(value: u32) -> u32 {
    match value >> 29 {
        0x1 => value & 0xffff,
        0x2 => {
            if value & 1 != 0 {
                32
            } else {
                16
            }
        }
        0x3 => 32,
        _ => 0,
    }
}

fn mdec_status(input_words_remaining: u32) -> u32 {
    let busy = u32::from(input_words_remaining != 0) << 29;
    0x8004_0000 | busy
}

fn mdec_ready_status() -> u32 {
    mdec_status(0)
}

const MDEC_ZIGZAG: [usize; 64] = [
    0, 1, 8, 16, 9, 2, 3, 10, 17, 24, 32, 25, 18, 11, 4, 5, 12, 19, 26, 33, 40, 48, 41, 34, 27, 20,
    13, 6, 7, 14, 21, 28, 35, 42, 49, 56, 57, 50, 43, 36, 29, 22, 15, 23, 30, 37, 44, 51, 58, 59,
    52, 45, 38, 31, 39, 46, 53, 60, 61, 54, 47, 55, 62, 63,
];

fn decode_mdec_macroblocks(
    words: &[u32],
    quant_luma: &[u8; 64],
    quant_chroma: &[u8; 64],
    scale_table: &[i16; 64],
    command: u32,
) -> Vec<u32> {
    let halfwords = mdec_halfwords(words);
    let mut cursor = 0usize;
    let mut macroblocks = Vec::new();
    let output_pixel_mask = mdec_rgb555_output_pixel_mask(command);

    while cursor < halfwords.len() {
        let Some(cr) = read_mdec_block(&halfwords, &mut cursor, quant_chroma, scale_table) else {
            break;
        };
        let Some(cb) = read_mdec_block(&halfwords, &mut cursor, quant_chroma, scale_table) else {
            break;
        };
        let Some(y0) = read_mdec_block(&halfwords, &mut cursor, quant_luma, scale_table) else {
            break;
        };
        let Some(y1) = read_mdec_block(&halfwords, &mut cursor, quant_luma, scale_table) else {
            break;
        };
        let Some(y2) = read_mdec_block(&halfwords, &mut cursor, quant_luma, scale_table) else {
            break;
        };
        let Some(y3) = read_mdec_block(&halfwords, &mut cursor, quant_luma, scale_table) else {
            break;
        };

        let mut pixels = [0_u16; 16 * 16];
        for row in 0..16 {
            for col in 0..16 {
                let y_block = match (row >= 8, col >= 8) {
                    (false, false) => &y0,
                    (false, true) => &y1,
                    (true, false) => &y2,
                    (true, true) => &y3,
                };
                let y = y_block[(row % 8) * 8 + (col % 8)];
                let chroma_index = (row / 2) * 8 + (col / 2);
                pixels[row * 16 + col] =
                    ycbcr_to_rgb555(y, cb[chroma_index], cr[chroma_index]) | output_pixel_mask;
            }
        }
        macroblocks.push(pixels);
    }

    let pixels = mdec_rgb555_output_pixels(&macroblocks);
    pack_rgb555_pixels(&pixels)
}

fn mdec_rgb555_output_pixels(macroblocks: &[[u16; 16 * 16]]) -> Vec<u16> {
    match native_mdec_rgb555_output_layout() {
        "strip-row" => flatten_mdec_rgb555_macroblocks_as_240p_strips(macroblocks)
            .unwrap_or_else(|| flatten_mdec_rgb555_macroblocks_raw(macroblocks)),
        "strip-column" => flatten_mdec_rgb555_macroblocks_as_240p_column_strips(macroblocks)
            .unwrap_or_else(|| flatten_mdec_rgb555_macroblocks_raw(macroblocks)),
        _ => flatten_mdec_rgb555_macroblocks_raw(macroblocks),
    }
}

fn native_mdec_rgb555_output_layout() -> &'static str {
    match std::env::var("BR2_NATIVE_MDEC_RGB555_OUTPUT_LAYOUT")
        .ok()
        .as_deref()
    {
        Some("strip-row") => "strip-row",
        Some("strip-column") => "strip-column",
        _ => "raw",
    }
}

fn flatten_mdec_rgb555_macroblocks_raw(macroblocks: &[[u16; 16 * 16]]) -> Vec<u16> {
    macroblocks
        .iter()
        .flat_map(|macroblock| macroblock.iter().copied())
        .collect()
}

#[cfg(test)]
fn flatten_mdec_rgb555_macroblocks(macroblocks: &[[u16; 16 * 16]]) -> Vec<u16> {
    if let Some(pixels) = flatten_mdec_rgb555_macroblocks_as_240p_strips(macroblocks) {
        return pixels;
    }

    flatten_mdec_rgb555_macroblocks_raw(macroblocks)
}

fn flatten_mdec_rgb555_macroblocks_as_240p_strips(
    macroblocks: &[[u16; 16 * 16]],
) -> Option<Vec<u16>> {
    const MDEC_240P_MACROBLOCK_ROWS: usize = 15;
    const MDEC_STRIP_MACROBLOCK_COLUMNS: usize = 4;
    const MDEC_STRIP_WIDTH_PIXELS: usize = MDEC_STRIP_MACROBLOCK_COLUMNS * 16;
    const MDEC_STRIP_HEIGHT_PIXELS: usize = 256;
    const MDEC_320X240_MACROBLOCKS: usize = 20 * MDEC_240P_MACROBLOCK_ROWS;

    if macroblocks.len() < MDEC_240P_MACROBLOCK_ROWS {
        return None;
    }

    let packed_len = if macroblocks.len().is_multiple_of(MDEC_240P_MACROBLOCK_ROWS) {
        macroblocks.len()
    } else if macroblocks.len() > MDEC_320X240_MACROBLOCKS {
        MDEC_320X240_MACROBLOCKS
    } else {
        return None;
    };
    let macroblock_columns = packed_len / MDEC_240P_MACROBLOCK_ROWS;
    if !(2..=64).contains(&macroblock_columns)
        || !macroblock_columns.is_multiple_of(MDEC_STRIP_MACROBLOCK_COLUMNS)
    {
        return None;
    }

    let strip_count = macroblock_columns / MDEC_STRIP_MACROBLOCK_COLUMNS;
    let packed_pixels = strip_count
        .saturating_mul(MDEC_STRIP_WIDTH_PIXELS)
        .saturating_mul(MDEC_STRIP_HEIGHT_PIXELS);
    let mut pixels = Vec::with_capacity(
        packed_pixels.saturating_add(
            macroblocks
                .len()
                .saturating_sub(packed_len)
                .saturating_mul(16 * 16),
        ),
    );
    for strip in 0..strip_count {
        let base_column = strip * MDEC_STRIP_MACROBLOCK_COLUMNS;
        for macroblock_row in 0..MDEC_240P_MACROBLOCK_ROWS {
            for pixel_row in 0..16 {
                for strip_column in 0..MDEC_STRIP_MACROBLOCK_COLUMNS {
                    let source_index = macroblock_row
                        .saturating_mul(macroblock_columns)
                        .saturating_add(base_column)
                        .saturating_add(strip_column);
                    let row_start = pixel_row * 16;
                    pixels.extend_from_slice(&macroblocks[source_index][row_start..row_start + 16]);
                }
            }
        }
        let padding_rows = MDEC_STRIP_HEIGHT_PIXELS - (MDEC_240P_MACROBLOCK_ROWS * 16);
        pixels.extend(
            std::iter::repeat(0).take(padding_rows.saturating_mul(MDEC_STRIP_WIDTH_PIXELS)),
        );
    }
    for macroblock in &macroblocks[packed_len..] {
        pixels.extend_from_slice(macroblock);
    }
    Some(pixels)
}

fn flatten_mdec_rgb555_macroblocks_as_240p_column_strips(
    macroblocks: &[[u16; 16 * 16]],
) -> Option<Vec<u16>> {
    const MDEC_240P_MACROBLOCK_ROWS: usize = 15;
    const MDEC_STRIP_MACROBLOCK_COLUMNS: usize = 4;
    const MDEC_STRIP_WIDTH_PIXELS: usize = MDEC_STRIP_MACROBLOCK_COLUMNS * 16;
    const MDEC_STRIP_HEIGHT_PIXELS: usize = 256;

    if macroblocks.len() < MDEC_240P_MACROBLOCK_ROWS
        || !macroblocks.len().is_multiple_of(MDEC_240P_MACROBLOCK_ROWS)
    {
        return None;
    }
    let macroblock_columns = macroblocks.len() / MDEC_240P_MACROBLOCK_ROWS;
    if !(4..=64).contains(&macroblock_columns)
        || !macroblock_columns.is_multiple_of(MDEC_STRIP_MACROBLOCK_COLUMNS)
    {
        return None;
    }

    let strip_count = macroblock_columns / MDEC_STRIP_MACROBLOCK_COLUMNS;
    let mut pixels =
        Vec::with_capacity(strip_count * MDEC_STRIP_WIDTH_PIXELS * MDEC_STRIP_HEIGHT_PIXELS);
    for strip in 0..strip_count {
        let base_column = strip * MDEC_STRIP_MACROBLOCK_COLUMNS;
        for macroblock_row in 0..MDEC_240P_MACROBLOCK_ROWS {
            for pixel_row in 0..16 {
                for strip_column in 0..MDEC_STRIP_MACROBLOCK_COLUMNS {
                    let source_index = (base_column + strip_column)
                        .saturating_mul(MDEC_240P_MACROBLOCK_ROWS)
                        .saturating_add(macroblock_row);
                    let row_start = pixel_row * 16;
                    pixels.extend_from_slice(&macroblocks[source_index][row_start..row_start + 16]);
                }
            }
        }
        pixels.extend(std::iter::repeat_n(
            0,
            (MDEC_STRIP_HEIGHT_PIXELS - MDEC_240P_MACROBLOCK_ROWS * 16) * MDEC_STRIP_WIDTH_PIXELS,
        ));
    }
    Some(pixels)
}

fn mdec_rgb555_output_pixel_mask(command: u32) -> u16 {
    if command & (1 << 25) != 0 { 0x8000 } else { 0 }
}

fn mdec_bytes(words: &[u32]) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(words.len().saturating_mul(4));
    for word in words {
        bytes.extend_from_slice(&word.to_le_bytes());
    }
    bytes
}

fn mdec_halfwords(words: &[u32]) -> Vec<u16> {
    let mut halfwords = Vec::with_capacity(words.len().saturating_mul(2));
    for word in words {
        halfwords.push((word & 0xffff) as u16);
        halfwords.push((word >> 16) as u16);
    }
    halfwords
}

fn read_mdec_block(
    halfwords: &[u16],
    cursor: &mut usize,
    quant: &[u8; 64],
    scale_table: &[i16; 64],
) -> Option<[i16; 64]> {
    let first = loop {
        let word = *halfwords.get(*cursor)?;
        *cursor += 1;
        if word != 0xfe00 {
            break word;
        }
    };
    let qscale = ((first >> 10) & 0x3f) as i32;
    let dc = sign_extend_10(first & 0x03ff) as i32;
    let mut coefficients = [0_i32; 64];
    coefficients[0] = if qscale == 0 {
        saturate_mdec_coefficient(dc.saturating_mul(2))
    } else {
        saturate_mdec_coefficient(dc.saturating_mul(i32::from(quant[0])))
    };
    let mut zigzag_index = 0usize;

    while let Some(word) = halfwords.get(*cursor).copied() {
        *cursor += 1;
        if word == 0xfe00 {
            break;
        }
        let run = ((word >> 10) & 0x3f) as usize;
        zigzag_index = zigzag_index.saturating_add(run).saturating_add(1);
        if zigzag_index >= 64 {
            break;
        }
        let value = sign_extend_10(word & 0x03ff) as i32;
        if qscale == 0 {
            coefficients[zigzag_index] = saturate_mdec_coefficient(value.saturating_mul(2));
        } else {
            let natural_index = MDEC_ZIGZAG[zigzag_index];
            let quant_index = if native_mdec_quant_table_uses_natural_order() {
                natural_index
            } else {
                zigzag_index
            };
            coefficients[natural_index] = saturate_mdec_coefficient(
                value
                    .saturating_mul(i32::from(quant[quant_index]))
                    .saturating_mul(qscale)
                    .saturating_add(4)
                    / 8,
            );
        }
    }

    Some(idct_8x8_with_optional_scale(&coefficients, scale_table))
}

fn saturate_mdec_coefficient(value: i32) -> i32 {
    value.clamp(-0x400, 0x3ff)
}

fn native_mdec_quant_table_uses_natural_order() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BR2_NATIVE_MDEC_QUANT_NATURAL_ORDER")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

fn idct_8x8(coefficients: &[i32; 64]) -> [i16; 64] {
    let mut block = [0_i16; 64];
    let basis = mdec_idct_basis();
    for output_index in 0..64 {
        let mut sum = 0.0_f64;
        for coefficient_index in 0..64 {
            sum += coefficients[coefficient_index] as f64 * basis[output_index][coefficient_index];
        }
        block[output_index] = sum.round().clamp(i16::MIN as f64, i16::MAX as f64) as i16;
    }
    block
}

fn idct_8x8_with_optional_scale(coefficients: &[i32; 64], scale_table: &[i16; 64]) -> [i16; 64] {
    if scale_table.iter().all(|value| *value == 0) {
        return idct_8x8(coefficients);
    }

    let mut intermediate = [0_i64; 64];
    for x in 0..8 {
        for y in 0..8 {
            let mut sum = 0_i64;
            for u in 0..8 {
                sum += i64::from(coefficients[u * 8 + x]) * i64::from(scale_table[y * 8 + u]);
            }
            intermediate[x + y * 8] = sum;
        }
    }

    let mut block = [0_i16; 64];
    for y in 0..8 {
        for x in 0..8 {
            let mut sum = 0_i64;
            for u in 0..8 {
                sum += intermediate[u + y * 8] * i64::from(scale_table[x * 8 + u]);
            }
            let rounded = (sum >> 32) + ((sum >> 31) & 1);
            block[y * 8 + x] = sign_extend_9(rounded as i32).clamp(-128, 127);
        }
    }
    block
}

fn sign_extend_9(value: i32) -> i16 {
    let value = value & 0x01ff;
    if value & 0x0100 != 0 {
        (value | !0x01ff) as i16
    } else {
        value as i16
    }
}

fn mdec_idct_basis() -> &'static [[f64; 64]; 64] {
    static BASIS: OnceLock<[[f64; 64]; 64]> = OnceLock::new();
    BASIS.get_or_init(|| {
        let mut basis = [[0.0_f64; 64]; 64];
        for y in 0..8 {
            for x in 0..8 {
                let output_index = y * 8 + x;
                for v in 0..8 {
                    for u in 0..8 {
                        let cu = if u == 0 {
                            std::f64::consts::FRAC_1_SQRT_2
                        } else {
                            1.0
                        };
                        let cv = if v == 0 {
                            std::f64::consts::FRAC_1_SQRT_2
                        } else {
                            1.0
                        };
                        let basis_x =
                            (((2 * x + 1) * u) as f64 * std::f64::consts::PI / 16.0).cos();
                        let basis_y =
                            (((2 * y + 1) * v) as f64 * std::f64::consts::PI / 16.0).cos();
                        basis[output_index][v * 8 + u] = cu * cv * basis_x * basis_y / 4.0;
                    }
                }
            }
        }
        basis
    })
}

fn sign_extend_10(value: u16) -> i16 {
    let value = value & 0x03ff;
    if value & 0x0200 != 0 {
        (value | 0xfc00) as i16
    } else {
        value as i16
    }
}

fn ycbcr_to_rgb555(y: i16, cb: i16, cr: i16) -> u16 {
    let y = 128 + i32::from(y);
    let cb = i32::from(cb);
    let cr = i32::from(cr);
    let r = y + ((1436 * cr) >> 10);
    let g = y - (((352 * cb) + (731 * cr)) >> 10);
    let b = y + ((1815 * cb) >> 10);
    rgb888_to_rgb555_components(clamp_u8(r), clamp_u8(g), clamp_u8(b))
}

fn clamp_u8(value: i32) -> u8 {
    value.clamp(0, u8::MAX as i32) as u8
}

fn rgb888_to_rgb555_components(r: u8, g: u8, b: u8) -> u16 {
    ((u16::from(r) >> 3) & 0x1f)
        | (((u16::from(g) >> 3) & 0x1f) << 5)
        | (((u16::from(b) >> 3) & 0x1f) << 10)
}

fn pack_rgb555_pixels(pixels: &[u16]) -> Vec<u32> {
    pixels
        .chunks(2)
        .map(|chunk| {
            let low = u32::from(chunk[0]);
            let high = chunk.get(1).copied().map(u32::from).unwrap_or(0);
            low | (high << 16)
        })
        .collect()
}

const SPU_REGISTER_COUNT: usize = ((SPU_REGION_END - SPU_REGION_START).div_ceil(2)) as usize;

#[derive(Clone, Debug)]
pub struct Spu {
    registers: [u16; SPU_REGISTER_COUNT],
}

impl Default for Spu {
    fn default() -> Self {
        Self {
            registers: [0; SPU_REGISTER_COUNT],
        }
    }
}

impl Spu {
    fn read_u32(&self, address: u32) -> u32 {
        let index = spu_index(address);
        self.registers[index] as u32
    }

    fn write_u32(&mut self, address: u32, value: u32) {
        let index = spu_index(address);
        self.registers[index] = value as u16;
    }
}

fn spu_index(address: u32) -> usize {
    (((address - SPU_REGION_START) / 2) as usize).min(255)
}

fn clear_if(state: &mut u16, mask: u16, pressed: bool) {
    if pressed {
        *state &= !mask;
    }
}

