    fn fill_multicolor_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let red = 24 + ((x * 13 + y * 5) % 224) as u32;
                let green = 16 + ((x * 7 + y * 17) % 224) as u32;
                let blue = 32 + ((x * 19 + y * 11) % 208) as u32;
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    (red << 16) | (green << 8) | blue,
                );
            }
        }
    }

    fn fill_sparse_multicolor_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        const BLOCK_WIDTH: usize = 32;
        const BLOCK_HEIGHT: usize = 24;

        for block_y in (0..height).step_by(BLOCK_HEIGHT) {
            for block_x in (0..width).step_by(BLOCK_WIDTH) {
                let block_index_x = block_x / BLOCK_WIDTH;
                let block_index_y = block_y / BLOCK_HEIGHT;
                let hash = (block_index_x as u32)
                    .wrapping_mul(73)
                    .wrapping_add((block_index_y as u32).wrapping_mul(151))
                    .wrapping_add(
                        (block_index_x as u32)
                            .wrapping_mul(block_index_y as u32)
                            .wrapping_mul(17),
                    );
                if hash % 100 >= 24 {
                    continue;
                }

                let block_width = BLOCK_WIDTH.min(width.saturating_sub(block_x));
                let block_height = BLOCK_HEIGHT.min(height.saturating_sub(block_y));
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(block_x) as i32,
                    y_offset.saturating_add(block_y) as i32,
                    block_width as i32,
                    block_height as i32,
                    0x0060_8058,
                );
                for y in 0..block_height {
                    for x in 0..block_width {
                        let absolute_x = block_x.saturating_add(x);
                        let absolute_y = block_y.saturating_add(y);
                        let red = 48 + ((absolute_x * 11 + absolute_y * 3) % 96) as u32;
                        let green = 96 + ((absolute_x * 7 + absolute_y * 19) % 128) as u32;
                        let blue = 72 + ((absolute_x * 13 + absolute_y * 5) % 128) as u32;
                        io.gpu.framebuffer.fill_rect_unclipped(
                            x_offset.saturating_add(absolute_x) as i32,
                            y_offset.saturating_add(absolute_y) as i32,
                            1,
                            1,
                            (red << 16) | (green << 8) | blue,
                        );
                    }
                }
            }
        }
    }

    fn fill_dark_live_stage_field(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        let active_height = height * 3 / 4;
        for y in 0..active_height {
            for x in 0..width {
                let hash = (x * 17 + y * 31 + (x * y) / 13) % 100;
                if hash >= 72 {
                    continue;
                }

                let red = ((x * 11 + y * 7) % 192) as u32;
                let green = ((x * 5 + y * 19) % 176) as u32;
                let blue = ((x * 23 + y * 3) % 224) as u32;
                let color = match (x / 13 + y / 9 + hash) % 5 {
                    0 => ((64 + red) << 16) | ((green / 2) << 8) | (blue / 3),
                    1 => ((red / 3) << 16) | ((72 + green) << 8) | (blue / 2),
                    2 => ((red / 2) << 16) | ((green / 3) << 8) | (48 + blue),
                    3 => ((32 + red / 2) << 16) | ((48 + green / 2) << 8) | (64 + blue / 2),
                    _ => ((24 + red / 4) << 16) | ((24 + green / 4) << 8) | (40 + blue / 4),
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }

        let hud_y = y_offset + height * 58 / 100;
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset.saturating_add(width * 8 / 100) as i32,
            hud_y as i32,
            (width * 34 / 100) as i32,
            (height / 16).max(3) as i32,
            0x00e8_e8_e8,
        );
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset.saturating_add(width * 76 / 100) as i32,
            hud_y as i32,
            (width * 18 / 100) as i32,
            (height / 14).max(3) as i32,
            0x00d8_d8_d8,
        );
    }

    fn fill_br2_character_select_live_field(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let phase = (x / 4 + y / 4) % 10;
                let noise = ((x * 17 + y * 31 + (x * y) / 211) % 96) as u32;
                let color = match phase {
                    0 => {
                        let v = (noise / 8).min(24);
                        (v << 16) | (v << 8) | v
                    }
                    1 => {
                        let v = (noise / 6).min(28);
                        ((v + 2) << 16) | ((v + 1) << 8) | v
                    }
                    2 => (0x0090_1010 | ((noise + 64).min(255) << 16)) & 0x00ff_ffff,
                    3 => {
                        let red = 160 + noise.min(80);
                        let blue = 144 + ((noise * 3) % 96);
                        (red << 16) | 0x0010_00 | blue
                    }
                    4 => {
                        let green = 144 + noise.min(96);
                        let blue = 144 + ((noise * 5) % 96);
                        0x0010_0000 | (green << 8) | blue
                    }
                    5 => {
                        let blue = 208 + noise.min(47);
                        0x0020_1000 | blue
                    }
                    6 => {
                        let red = 176 + noise.min(72);
                        let blue = 168 + ((noise * 7) % 80);
                        (red << 16) | 0x0028_00 | blue
                    }
                    _ => {
                        let red = 48 + ((x * 13 + y * 5 + noise as usize) % 176) as u32;
                        let green = 64 + ((x * 7 + y * 17 + noise as usize) % 160) as u32;
                        let blue = 56 + ((x * 19 + y * 11 + noise as usize) % 168) as u32;
                        (red << 16) | (green << 8) | blue
                    }
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }

        let ok_x = x_offset + width * 63 / 100;
        let ok_y = y_offset + height * 48 / 100;
        for row in 0..5 {
            io.gpu.framebuffer.fill_rect_unclipped(
                ok_x.saturating_add(row * 18) as i32,
                ok_y.saturating_add(row * 7) as i32,
                (width / 8).max(24) as i32,
                4,
                0x00f8_f0c0,
            );
        }
    }

    fn fill_br2_sparse_character_select_hud_field(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            y_offset as i32,
            width as i32,
            height as i32,
            0,
        );

        for side in [0usize, width * 56 / 100] {
            let name_x = x_offset + side + width / 14;
            let name_y = y_offset + height / 8;
            for y in 0..height / 6 {
                for x in 0..width / 3 {
                    let stripe = (x / 6 + y / 3) % 7;
                    let color = match stripe {
                        0 => 0x00ff_c020,
                        1 => 0x00ff_f050,
                        2 => 0x00f8_f8f8,
                        3 => 0x0068_6870,
                        4 => 0x0038_3840,
                        5 => 0x0000_50e0,
                        _ => 0,
                    };
                    if color != 0 {
                        io.gpu.framebuffer.fill_rect_unclipped(
                            name_x.saturating_add(x) as i32,
                            name_y.saturating_add(y) as i32,
                            1,
                            1,
                            color,
                        );
                    }
                }
            }
        }

        for (base_x, palette_shift) in [(width / 10, 0usize), (width * 58 / 100, 3usize)] {
            for y in 0..height / 3 {
                for x in 0..width / 4 {
                    if (x / 5 + y / 4) % 9 >= 6 {
                        continue;
                    }
                    let color = match (x / 9 + y / 7 + palette_shift) % 6 {
                        0 => 0x0000_40d8,
                        1 => 0x0000_d050,
                        2 => 0x0000_f0f0,
                        3 => 0x00d8_2020,
                        4 => 0x00f0_d020,
                        _ => 0x0010_1018,
                    };
                    io.gpu.framebuffer.fill_rect_unclipped(
                        x_offset.saturating_add(base_x + x) as i32,
                        y_offset.saturating_add(height / 3 + y) as i32,
                        1,
                        1,
                        color,
                    );
                }
            }
        }

        let select_x = x_offset + width * 42 / 100;
        let select_y = y_offset + height * 54 / 100;
        for row in 0..5 {
            let y = select_y + row * 7;
            for x in 0..width / 6 {
                let color = if (x / 5 + row) % 3 == 0 {
                    0x00ff_ffff
                } else {
                    0x00e8_2020
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    select_x.saturating_add(x) as i32,
                    y as i32,
                    1,
                    3,
                    color,
                );
            }
        }

        for y in height * 4 / 5..height {
            io.gpu.framebuffer.fill_rect_unclipped(
                x_offset as i32,
                y_offset.saturating_add(y) as i32,
                width as i32,
                1,
                0,
            );
        }
    }

