    fn stamp_title_logo_overlay_marks(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        let title_x = x_offset + width * 52 / 100;
        let title_y = y_offset + height * 48 / 100;
        let title_width = width * 47 / 100;
        let title_height = height * 36 / 100;
        io.gpu.framebuffer.fill_rect_unclipped(
            title_x as i32,
            title_y as i32,
            title_width as i32,
            title_height as i32,
            0,
        );

        for y in title_y..title_y + title_height {
            for x in title_x..title_x + title_width {
                let local_x = x - title_x;
                let local_y = y - title_y;
                if local_y % 18 < 10 && local_x < title_width * 2 / 3 {
                    io.gpu
                        .framebuffer
                        .fill_rect_unclipped(x as i32, y as i32, 1, 1, 0x00d8_1818);
                } else if (local_x + local_y * 3) % 23 < 5 {
                    io.gpu
                        .framebuffer
                        .fill_rect_unclipped(x as i32, y as i32, 1, 1, 0x00f0_f0f0);
                }
            }
        }
    }

    fn fill_primitive_workspace_artifact(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let color = if y < height / 5 {
                    match (x.saturating_mul(5) / width.max(1)).min(4) {
                        0 | 1 => 0x00ff_00d8,
                        2 => 0x00e0_0038,
                        3 => 0x0018_1870,
                        _ => 0x0020_d888,
                    }
                } else if y.saturating_mul(5) > height + x.saturating_mul(2) {
                    match (x.saturating_mul(17).saturating_add(y.saturating_mul(29))) % 19 {
                        0..=5 => 0,
                        6..=10 => 0x0000_e8f0,
                        11..=14 => 0x00f0_00e8,
                        15..=16 => 0x0088_0800,
                        _ => 0x0008_0808,
                    }
                } else {
                    match ((x / 32).saturating_add(y / 24)) % 4 {
                        0 => 0x00a8_c0c8,
                        1 => 0x00f8_f8f8,
                        2 => 0x00c8_d8e8,
                        _ => 0x00e8_20e0,
                    }
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    fn fill_glyph_texture_atlas_page(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            y_offset as i32,
            width as i32,
            height as i32,
            0x0008_0808,
        );
        for cell_y in (0..height).step_by(12) {
            for cell_x in (0..width).step_by(16) {
                let red = 32 + ((cell_x * 5 + cell_y * 3) % 224) as u32;
                let green = 24 + ((cell_x * 7 + cell_y * 11) % 224) as u32;
                let blue = 40 + ((cell_x * 13 + cell_y * 17) % 208) as u32;
                let color = (red << 16) | (green << 8) | blue;
                let x = x_offset.saturating_add(cell_x) as i32;
                let y = y_offset.saturating_add(cell_y) as i32;
                io.gpu.framebuffer.fill_rect_unclipped(x, y, 10, 2, color);
                io.gpu
                    .framebuffer
                    .fill_rect_unclipped(x, y + 4, 2, 7, color);
                if (cell_x / 16 + cell_y / 12) % 2 == 0 {
                    io.gpu
                        .framebuffer
                        .fill_rect_unclipped(x + 4, y + 6, 7, 2, 0x00ff_ffff);
                }
            }
        }
    }

    fn fill_low_bucket_glyph_texture_atlas_page(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        const PALETTE: [u32; 6] = [
            0x0008_0808,
            0x0030_3030,
            0x0068_6868,
            0x00a0_a0a0,
            0x00d8_d8d8,
            0x00ff_ffff,
        ];
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            y_offset as i32,
            width as i32,
            height as i32,
            PALETTE[0],
        );
        for cell_y in (0..height).step_by(12) {
            for cell_x in (0..width).step_by(16) {
                let color = PALETTE[((cell_x / 16) + (cell_y / 12)) % PALETTE.len()];
                let x = x_offset.saturating_add(cell_x) as i32;
                let y = y_offset.saturating_add(cell_y) as i32;
                io.gpu.framebuffer.fill_rect_unclipped(x, y, 10, 2, color);
                io.gpu
                    .framebuffer
                    .fill_rect_unclipped(x, y + 4, 2, 7, color);
                if (cell_x / 16 + cell_y / 12) % 3 == 0 {
                    io.gpu
                        .framebuffer
                        .fill_rect_unclipped(x + 4, y + 6, 7, 2, PALETTE[5]);
                }
            }
        }
    }

    fn fill_dense_caption_texture_page(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let in_caption_band = y >= height.saturating_mul(4) / 5;
                let logo_column = x >= width / 2 && ((x / 8 + y / 6) % 4 == 0);
                let caption_stroke = in_caption_band && (x / 12 + y / 4) % 2 == 0;
                let color = if caption_stroke {
                    0x00f0_f0f0
                } else if logo_column {
                    0x00d8_d010
                } else {
                    0x0008_0808
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    fn fill_dense_noisy_caption_texture_page(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let in_caption_band = y >= height.saturating_mul(4) / 5;
                let noise = (x
                    .saturating_mul(17)
                    .saturating_add(y.saturating_mul(31))
                    .saturating_add((x ^ y).saturating_mul(7)))
                    % 100;
                let color = if in_caption_band && noise < 35 {
                    0x00f0_f0f0
                } else if noise < 25 {
                    0x00d8_d010
                } else {
                    0x0008_0808
                };
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    fn fill_br2_low_color_select_texture_atlas_overlay(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            y_offset as i32,
            width as i32,
            height as i32,
            0,
        );
        let palette = [
            0x0048_1008,
            0x0058_1810,
            0x0060_2018,
            0x0068_2410,
            0x0070_2818,
            0x0050_140c,
        ];
        let y_start = height / 12;
        let y_end = height * 29 / 48;
        let x_start = width / 32;
        let x_end = width * 31 / 32;
        for y in y_start..y_end {
            for x in x_start..x_end {
                let hash = (x / 5)
                    .saturating_add(y / 7)
                    .saturating_add(x.saturating_mul(y) / 97);
                if hash % 20 >= 10 {
                    continue;
                }
                let color = palette[(hash / 3) % palette.len()];
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    fn fill_psx24_glyph_texture_atlas_page(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        let row_bytes = width.saturating_mul(3);
        let mut bytes = vec![8_u8; row_bytes.saturating_mul(height)];
        for cell_y in (0..height).step_by(12) {
            for cell_x in (0..width).step_by(16) {
                let red = 32 + ((cell_x * 5 + cell_y * 3) % 224) as u8;
                let green = 24 + ((cell_x * 7 + cell_y * 11) % 224) as u8;
                let blue = 40 + ((cell_x * 13 + cell_y * 17) % 208) as u8;
                for dy in 0..2 {
                    for dx in 0..10 {
                        write_psx24_test_pixel(
                            &mut bytes,
                            width,
                            cell_x + dx,
                            cell_y + dy,
                            red,
                            green,
                            blue,
                        );
                    }
                }
                for dy in 4..11 {
                    for dx in 0..2 {
                        write_psx24_test_pixel(
                            &mut bytes,
                            width,
                            cell_x + dx,
                            cell_y + dy,
                            red,
                            green,
                            blue,
                        );
                    }
                }
                if (cell_x / 16 + cell_y / 12) % 2 == 0 {
                    for dy in 6..8 {
                        for dx in 4..11 {
                            write_psx24_test_pixel(
                                &mut bytes,
                                width,
                                cell_x + dx,
                                cell_y + dy,
                                0xff,
                                0xff,
                                0xff,
                            );
                        }
                    }
                }
            }
        }

        for y in 0..height {
            let row = y.saturating_mul(row_bytes);
            for word_x in 0..row_bytes.div_ceil(2) {
                let low = bytes[row + word_x * 2];
                let high = bytes.get(row + word_x * 2 + 1).copied().unwrap_or(0);
                io.gpu.framebuffer.set_raw_pixel(
                    x_offset.saturating_add(word_x) as i32,
                    y_offset.saturating_add(y) as i32,
                    u16::from(low) | (u16::from(high) << 8),
                );
            }
        }
    }

    fn write_psx24_test_pixel(
        bytes: &mut [u8],
        width: usize,
        x: usize,
        y: usize,
        red: u8,
        green: u8,
        blue: u8,
    ) {
        if x >= width {
            return;
        }
        let row_bytes = width.saturating_mul(3);
        let Some(index) = y
            .checked_mul(row_bytes)
            .and_then(|row| row.checked_add(x.saturating_mul(3)))
        else {
            return;
        };
        if index + 2 >= bytes.len() {
            return;
        }
        bytes[index] = red;
        bytes[index + 1] = green;
        bytes[index + 2] = blue;
    }

    fn fill_intro_caption_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        fill_multicolor_scene(io, x_offset, y_offset, width, height);
        let band_start = y_offset + height * 4 / 5;
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            band_start as i32,
            width as i32,
            (height - height * 4 / 5) as i32,
            0,
        );
        for y in y_offset + height * 9 / 10..(y_offset + height * 9 / 10 + 8).min(y_offset + height)
        {
            for x in x_offset + width / 5..x_offset + width * 4 / 5 {
                if (x + y) % 6 < 3 {
                    io.gpu
                        .framebuffer
                        .fill_rect_unclipped(x as i32, y as i32, 1, 1, 0x00ef_efef);
                }
            }
        }
    }

    fn fill_thin_caption_text_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        fill_multicolor_scene(io, x_offset, y_offset, width, height);
        let bottom_band_start = y_offset + height * 4 / 5;
        let dark_band_height = (height / 20).max(1);
        io.gpu.framebuffer.fill_rect_unclipped(
            x_offset as i32,
            bottom_band_start as i32,
            width as i32,
            dark_band_height as i32,
            0,
        );
        let text_start = bottom_band_start + dark_band_height + (height / 80).max(1);
        for y in text_start..(text_start + (height / 25).max(4)).min(y_offset + height) {
            for x in (x_offset + width / 5..x_offset + width * 4 / 5).step_by(9) {
                for stroke_x in x..(x + 4).min(x_offset + width) {
                    io.gpu.framebuffer.fill_rect_unclipped(
                        stroke_x as i32,
                        y as i32,
                        1,
                        1,
                        0x00ef_efef,
                    );
                }
            }
        }
    }

    fn fill_periodic_horizontal_ghosting_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        for y in 0..height {
            for x in 0..width {
                let phase = x % 64;
                let red = 24 + ((phase * 5 + y * 3) % 224) as u32;
                let green = 16 + ((phase * 11 + y * 7) % 224) as u32;
                let blue = 32 + ((phase * 17 + y * 13) % 208) as u32;
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    (red << 16) | (green << 8) | blue,
                );
            }
        }
    }

    fn fill_low_color_periodic_horizontal_ghosting_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        const COLORS: [u32; 4] = [0x00f0_9078, 0x00d8_7858, 0x00ff_a088, 0x00c8_6848];
        for y in 0..height {
            for x in 0..width {
                let color = COLORS[((x / 8) + (y / 16)) % COLORS.len()];
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    fn fill_low_bucket_playfield_scene(
        io: &mut Io,
        x_offset: usize,
        y_offset: usize,
        width: usize,
        height: usize,
    ) {
        const COLORS: [u32; 12] = [
            0x00f0_2020,
            0x0020_f020,
            0x0020_20f0,
            0x00f0_e020,
            0x0020_f0e0,
            0x00e0_20f0,
            0x00f0_8020,
            0x0080_f020,
            0x0020_80f0,
            0x00f0_2080,
            0x0020_f080,
            0x0080_20f0,
        ];
        for y in 0..height {
            for x in 0..width {
                let color = COLORS[((x / 4) + (y / 3) * 5) % COLORS.len()];
                io.gpu.framebuffer.fill_rect_unclipped(
                    x_offset.saturating_add(x) as i32,
                    y_offset.saturating_add(y) as i32,
                    1,
                    1,
                    color,
                );
            }
        }
    }

    #[test]
    fn register_metadata_is_unique_and_inside_io_region() {
        for (index, register) in IO_REGISTER_MAP.iter().enumerate() {
            assert!(
                is_io_register_address(register.address),
                "{} address {:#010x} is outside IO region",
                register.name,
                register.address
            );

            for previous in &IO_REGISTER_MAP[..index] {
                assert_ne!(
                    register.address, previous.address,
                    "{} duplicates {} at {:#010x}",
                    register.name, previous.name, register.address
                );
            }
        }
    }

    #[test]
    fn range_metadata_covers_dma_padding_and_spu_window() {
        let dma_interrupt = io_register(DMA_INTERRUPT).expect("DMA interrupt metadata");
        assert_eq!(dma_interrupt.device, IoDevice::Dma);

        let dma_padding = io_register_range(0x1f80_10fc).expect("DMA range metadata");
        assert_eq!(dma_padding.name, "DMA_CHANNEL_WINDOW");
        assert_eq!(dma_padding.device, IoDevice::Dma);
        assert!(dma_padding.access.writable());

        let spu = io_register_range(SPU_REGION_START).expect("SPU range metadata");
        assert_eq!(spu.device, IoDevice::Spu);
        assert!(spu.access.readable());
        assert!(spu.access_widths & ACCESS_WIDTH_16 != 0);
    }

    #[test]
    fn io_access_uses_named_register_map_addresses() {
        let mut io = Io::default();
        io.irq.status = 0xffff;

        io.write_u32(IRQ_STATUS, 0x00ff);
        io.write_u32(IRQ_MASK, 0x0101);
        io.write_u32(SIO_DATA, 0x1234);
        io.write_u32(GPU_GP1, 0x0300_0000);

        assert_eq!(io.read_u32(IRQ_STATUS), 0x00ff);
        assert_eq!(io.read_u32(IRQ_MASK), 0x0101);
        assert_eq!(io.controller.last_write, 0x1234);
        assert_eq!(io.gpu.status & (1 << 23), 0);
    }

    #[test]
    fn sio_data_write_raises_controller_irq_until_control_ack() {
        let mut io = Io::default();

        io.write_u8(SIO_DATA, 0x01);

        assert_eq!(io.irq.status & IRQ_CONTROLLER, IRQ_CONTROLLER);
        assert_eq!(
            io.controller.status & SIO_STATUS_IRQ_REQUEST,
            SIO_STATUS_IRQ_REQUEST
        );

        io.write_u16(SIO_CONTROL, 0x0010);

        assert_eq!(io.irq.status & IRQ_CONTROLLER, 0);
        assert_eq!(io.controller.status & SIO_STATUS_IRQ_REQUEST, 0);
    }

