        assert!(
            playability.contains("\"actual_display_source\":\"gp1_display_area_active_field\""),
            "{playability}"
        );
        assert!(
            playability.contains("\"reason\":\"single_field_scene_prefers_active_field\""),
            "{playability}"
        );
