    fn br2_palette_copy_preservation_rejects_normal_vram_copies() {
        let linked = GpuCommandSource::dma_linked_list(0x003b_00c4, Some(0x802d_080c));
        let cpu = GpuCommandSource::cpu_io(GPU_GP0, Some(0x8034_22bc));
        let blank = GpuTransferRegionStats {
            pixels: 512,
            nonzero_pixels: 0,
            unique_colors: 1,
            checksum: 0,
        };
        let populated = GpuTransferRegionStats {
            pixels: 512,
            nonzero_pixels: 512,
            unique_colors: 239,
            checksum: 0,
        };

        for (source_x, source_y, dest_x, dest_y, width, height, source, enabled) in [
            (48, 496, 48, 480, 32, 16, Some(&linked), false),
            (48, 496, 48, 480, 32, 16, Some(&cpu), true),
            (48, 496, 48, 480, 16, 16, Some(&linked), true),
            (48, 480, 48, 496, 32, 16, Some(&linked), true),
            (96, 496, 96, 480, 32, 16, Some(&linked), true),
        ] {
            assert!(
                !should_preserve_br2_populated_palette_on_blank_copy_with_policy(
                    source_x, source_y, dest_x, dest_y, width, height, blank, populated, source,
                    enabled,
                )
            );
        }
    }

    #[test]
    fn gpu_gp0_flat_quad_honors_semi_transparency() {
        let mut io = Io::default();

        io.write_u32(GPU_GP0, 0x0200_00ff);
        io.write_u32(GPU_GP0, 0x0000_0000);
        io.write_u32(GPU_GP0, 0x0004_0004);

        io.write_u32(GPU_GP0, 0x2aff_0000);
        io.write_u32(GPU_GP0, 0x0000_0000);
        io.write_u32(GPU_GP0, 0x0003_0000);
        io.write_u32(GPU_GP0, 0x0000_0003);
        io.write_u32(GPU_GP0, 0x0003_0003);

        let blended = io.gpu.framebuffer.pixel(1, 1);
        assert_ne!(blended, 0x00ff_0000);
        assert_ne!(blended, 0x0000_00ff);
        assert!(blended & 0x00ff_0000 != 0);
        assert!(blended & 0x0000_00ff != 0);
    }

    #[test]
    fn gpu_gp0_shaded_quad_interpolates_vertex_colors() {
        let mut io = Io::default();

        io.write_u32(GPU_GP0, 0x3800_00ff);
        io.write_u32(GPU_GP0, 0x000a_000a);
        io.write_u32(GPU_GP0, 0x0000_ff00);
        io.write_u32(GPU_GP0, 0x000a_000e);
        io.write_u32(GPU_GP0, 0x00ff_0000);
        io.write_u32(GPU_GP0, 0x000e_000a);
        io.write_u32(GPU_GP0, 0x00ff_ffff);
        io.write_u32(GPU_GP0, 0x000e_000e);

        let top_left = io.gpu.framebuffer.pixel(10, 10);
        let top_right = io.gpu.framebuffer.pixel(13, 11);
        let bottom_left = io.gpu.framebuffer.pixel(11, 13);

        assert!(
            (top_left & 0x00ff_0000) > (top_left & 0x0000_ff00),
            "top_left={top_left:#08x}"
        );
        assert!(
            (top_right & 0x0000_ff00) > (top_right & 0x00ff_0000),
            "top_right={top_right:#08x}"
        );
        assert!(
            (bottom_left & 0x0000_00ff) > (bottom_left & 0x00ff_0000),
            "bottom_left={bottom_left:#08x}"
        );
    }

